(window.GIM_TS=window.GIM_TS||{})["Avodah Zarah.4"]={"from":96,"a":[["\u0003במקורבות נמי\u0004 \u0005[גם כן],\u0006 \u0003דאיכא למימר מיניה נפל\u0004 \u0005[שיש לומר\u0006 ש\u0005ממנו נפלו]\u0006 — \u0003דברי הכל אסורות, כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים]\u0006 — \u0003במרוחקות.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"בצד מרקוליס\" קתני\u0004 \u0005[שנה],\u0006 משמע שמדובר פה במקורבות! ומשיבים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"בצד\"? בצד ארבע אמות דידיה\u0004 \u0005[שלו].\u0006","ובכך נחלקו: \u0003ר' ישמעאל סבר\u0004 \u0005[סבור]:\u0006 \u0003עושין מרקוליס קטן בצד מרקוליס גדול,\u0004 שפעמים עושים מלכתחילה גל קטן ליד הגל הגדול, ולכן \u0003שלש דדמיין\u0004 \u0005[ש\u0006הן \u0005דומות]\u0006 \u0003למרקוליס\u0004 גמור — \u0003אסורות, שתים\u0004 — \u0003מותרות.\u0004 ואילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003אין עושין מרקוליס קטן בצד מרקוליס גדול,\u0004 ולכן \u0003לא שנא\u0004 \u0005[שונה]\u0006 \u0003שלש ולא שנא\u0004 \u0005[שונה]\u0006 \u0003שתים,\u0004 אם היו \u0003נראות עמו\u0004 — \u0003אסורות,\u0004 מחשש שמא נפלו ממנו, \u0003שאין נראות עמו\u0004 — \u0003מותרות.\u0004","ודנים בהסבר זה של ר' יוחנן למשנה. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בידוע שנשרו ממנו\u0004 — \u0003דברי הכל אסורות. ורמינהי\u0004 \u0005[ומשליכים,\u0006 מביאים סתירה לכך ממקור אחר\u0005],\u0006 ששנינו בברייתא: \u0003אבנים שנשרו מן המרקוליס,\u0004 אם היו \u0003נראות עמו\u0004 — \u0003אסורות, שאין נראות עמו\u0004 — \u0003מותרות. ור' ישמעאל אומר: שלש\u0004 — \u0003אסורות, שתים\u0004 — \u0003מותרות.\u0004 הרי שגם כשידוע שנשרו מחלוקת! \u0003אמר רבא: לא תימא\u0004 \u0005[אל תאמר,\u0006 תגרוס בברייתא\u0005]\u0006 \u0003\"שנשרו\u0004 מן המרקוליס\", \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003\"שנמצאו\u0004 ליד מרקוליס\", ואין כאן ודאות בכך, אלא רק חשש, וכגון דברי ר' יוחנן.","ושואלים: \u0003וסבר\u0004 \u0005[וסבור]\u0006 \u0003ר' ישמעאל\u0004 ש\u0003שתים\u0004 בצד מרקוליס \u0003מותרות? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' ישמעאל אומר: שתים בתפיסה לו\u0004 שהיו מקורבות אליו — \u0003אסורות. שלש, אפילו מרוחקות\u0004 — \u0003אסורות!\u0004","\u0003אמר רבא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 שאסור, מדובר \u0003בתפיסה אחת\u0004 שאין הפסק ביניהן למרקוליס, \u0003כאן\u0004 שמותר, מדובר \u0003בשתי תפיסות\u0004 שיש הפסק מסויים בין זה לזה, \u0003והיכי דמי\u0004 \u0005[ואיך בדיוק מדובר]?\u0006 \u0003דאיכא גובהה ביני וביני\u0004 \u0005[שיש גובה,\u0006 מקום מוגבה \u0005בין זה לזה],\u0006 ואין לומר שממנו נפלו.","ושואלים: \u0003ומרקוליס כהאי גוונא מי הוי\u0004 \u0005[כגון זה האם ישנו],\u0006 שתי אבנים או שלש אבנים בכל צורה? \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003אלו הן אבני בית קוליס:\u0004 אם היתה אבן \u0003אחת מכאן ואחת מכאן ואחת על גביהן,\u0004 משמע שאפילו שלש אבנים סמוכות זו לזו אינו מרקוליס! \u0003אמר רבא: כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 — הרי זה \u0003בעיקר מרקוליס,\u0004 שכך עושים את הגל המקורי. אבל מה שמוסיפים לאחר מכן אינו בנוי דווקא בצורה זו.","מסופר, \u0003בי ינאי מלכא חרוב\u0004 \u0005[ביתו של ינאי המלך נחרב],\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 \u0003גוים אוקימו ביה\u0004 \u0005[\u0006ו\u0005העמידו בו]\u0006 \u0003מרקוליס, אתו גוים אחריני דלא פלחי\u0004 \u0005[באו גוים אחרים שאינם עובדים]\u0006 \u0003למרקוליס שקלינהו\u0004 \u0005[לקחו אותן]\u0006 את האבנים הללו, \u0003וחיפו בהן דרכים וסטרטאות\u0004 (רחובות), \u0003איכא רבנן דפרשי ואיכא רבנן דלא פרשי\u0004 \u0005[יש חכמים שפורשים\u0006 ואינם הולכים בדרכים הללו, \u0005ויש חכמים שאינם פורשים].\u0006","\u0003אמר ר' יוחנן: בנן של קדושים מהלך עליהן, ואנן\u0004 \u0005[ואנו]\u0006 \u0003נפרוש מהן?\u0004 אין צריכים לחשוש לכך. ושואלים: \u0003מאן ניהו\u0004 \u0005[מי הוא]\u0006 \u0003\"בנן של קדושים\"?\u0004 ומשיבים: \u0003ר' מנחם בר' סימאי\u0004 הוא, \u0003ואמאי קרו ליה\u0004 \u0005[ומדוע קוראים לו]\u0006 \u0003\"בנן של קדושים\"?\u0004 ש\u0003אפילו בצורתא דזוזא\u0004 \u0005[בצורה ש\u0006על \u0005המטבע]\u0006 \u0003לא\u0004 היה \u0003מיסתכל,\u0004 מחשש עבודה זרה.","ושואלים: \u0003מאי טעמא דמאן דפריש\u0004 \u0005[מה הטעם של מי שפורש]?\u0006 \u0003סבר לה כי הא דאמר\u0004 \u0005[סבור הוא כמו זו שאמר]\u0006 \u0003רב גידל אמר רב חייא בר יוסף אמר רב: מנין לתקרובת עבודה זרה שאין לה בטילה עולמית\u0004 (ביטול לעולם)? \u0003שנאמר: \"ויצמדו לבעל פעור ויאכלו זבחי מתים\"\u0004 (תהלים קו, כח), \u0003מה מת אין לו בטילה\u0004 ואסור \u0003לעולם, אף תקרובת עבודה זרה אין לה בטילה לעולם.\u0004","\u0003ומאן דלא פריש\u0004 \u0005[ומי שלא פורש\u0006 מהם\u0005],\u0006 \u0003אמר\u0004 \u0005[אומר]:\u0006 על מנת לאסור \u0003בעינא\u0004 \u0005[צריכים]\u0006 שתקרובת זו תהיה \u0003כעין פנים\u0004 כעין התקרובת שמקריבים בפנים, במקדש שלנו, \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי אין מקריבים אבנים במקדש.","\u0003אמר רב יוסף בר אבא: איקלע\u0004 \u0005[נזדמן]\u0006 \u0003רבה בר ירמיה לאתרין\u0004 \u0005[למקומנו],\u0006 \u0003ואתא ואייתי מתניתא בידיה\u0004 \u0005[ובא והביא ברייתא בידו]:\u0006 \u0003גוי שהביא אבנים מן המרקוליס וחיפה בהן דרכים וטרטיאות\u0004 —"],["\u0003מותרות, ישראל שהביא אבנים מן המרקוליס וחיפה בהן דרכים וסרטיאות\u0004 — \u0003אסורות, ולית נגר ולא בר נגר דיפרקינה\u0004 \u0005[ואין אומן ולא בן אומן שיפתור אותה],\u0006 כלומר, אין חכם או בן חכם שיכול לפתור את הקושי שיש בכך.","\u0003אמר רב ששת: אנא לא נגר אנא ולא בר\u0004 \u0003נגר אנא ופריקנא ליה\u0004 \u0005[אני לא אומן אני ולא בן אומן אני ואפתור אותה]:\u0006 \u0003מאי קושיא ליה\u0004 \u0005[מה קשה לו]\u0006 בענין זה? מה שאמר \u0003רב גידל,\u0004 שתקרובת עבודה זרה אין לה ביטול לעולם, אולם לכך יש תשובה: כדי לאסור התקרובת \u0003בעינא\u0004 \u0005[צריכים אנו]\u0006 שתהא \u0003כעין\u0004 תקרובת של \u0003פנים\u0004 של המקדש, \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שאין מקריבים אבנים במקדש.","ובדומה לזה \u0003אמר רב יוסף בר אבא: איקלע\u0004 \u0005[נזדמן]\u0006 \u0003רבה בר ירמיה לאתרין\u0004 \u0005[למקומנו],\u0006 \u0003ואתא ואייתי מתניתא בידיה\u0004 \u0005[ובא והביא ברייתא בידו]:\u0006 \u0003מתליעין\u0004 מוציאים תולעים מן האילן, \u0003ומזהמין\u0004 שמים זבל על פצע שבאילן \u0003בשביעית\u0004 (בשנת השמיטה), \u0003ואין מתליעין ומזהמין במועד\u0004 (בחול המועד).","\u0003כאן וכאן,\u0004 בין בשביעית בין בחול המועד, \u0003אין מגזמין\u0004 (גוזמים את הענפים לצורך האילן), \u0003ו\u0004אולם אם גזם קודם לכן, \u0003סכין שמן ל\u0004מקום ה\u0003גזום בין במועד בין בשביעית,\u0004 כדי שלא יינזק האילן. \u0003ולית נגר ולא בר נגר דיפרקינה\u0004 \u0005[ואין אומן ולא בן אומן שיפתור אותה].\u0006","\u0003אמר רבינא: אנא לא נגר אנא ולא בר נגר אנא ומפרקינא לה\u0004 \u0005[אני לא אומן אני ולא בן אומן אני ואפתור אותה]:\u0006 \u0003מאי קא קשיא ליה\u0004 \u0005[מה היה קשה לו]?\u0006 \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 מ\u0003מועד\u0004 על \u0003שביעית קא קשיא ליה\u0004 \u0005[קשה לו],\u0006 והשאלה היתה: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003שביעית דשרי\u0004 \u0005[שמותר]\u0006 להתליע ולזהם, \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003מועד\u0004 ש\u0003אסר?\u0004 על כך יש להשיב: \u0003מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 \u0003שביעית\u0004 — דווקא \u0003מלאכה\u0004 של עבודת האדמה \u0003אסור רחמנא\u0004 \u0005[אסרה התורה],\u0006 אבל \u0003טירחא\u0004 בכל דבר אחר \u0003שרי\u0004 \u0005[מותרת],\u0006 ואילו \u0003מועד\u0004 — \u0003אפילו טירחא נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור,\u0004 שהרי מועד הוא!","\u0003ואלא\u0004 מדין \u0003זיהום\u0004 על דין \u0003גיזום קא קשיא ליה\u0004 \u0005[קשה לו]:\u0006 \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003זיהום דשרי\u0004 \u0005[ש\u0006הוא \u0005מותר],\u0006 \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 \u0003גיזום\u0004 שהוא \u0003אסור?\u0004 על כך יש להשיב: \u0003מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 \u0003זיהום אוקומי אילנא, ושרי\u0004 \u0005[העמדת,\u0006 קיום \u0005האילן\u0006 הוא, שלא יתקלקל, \u0005ומותר],\u0006 \u0003גיזום אברויי אילנא\u0004 \u0005[הבריית האילן\u0006 הוא\u0005]\u0006 שמשביחו וגורם לו שיצמח יותר, \u0003ו\u0004דבר זה \u0003אסור!\u0004","\u0003ואלא\u0004 תאמר שמדין \u0003זיהום\u0004 על דין \u0003זיהום קא קשיא ליה\u0004 \u0005[קשה לו],\u0006 \u0003דקתני\u0004 \u0005[ששנינו]\u0006 בברייתא: \u0003מתליעין ומזהמין בשביעית. ורמינהי\u0004 \u0005[ומשליכים על כך]\u0006 ממה ששנינו במשנה במסכת שביעית: \u0003מזהמין את הנטיעות\u0004 (עצים צעירים), \u0003וכורכין אותן, וקוטמין אותן, ועושין להם בתים\u0004 (גדרות) מסביב, \u0003ומשקין אותן, עד ראש השנה\u0004 של שנת השביעית. ונדייק מכאן: \u0003עד ראש השנה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בשביעית\u0004 עצמה — \u0003לא!\u0004","על כך יש להשיב: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 יש להסביר זאת \u0003כ\u0004דברי \u0003רב עוקבא בר חמא,\u0004 ש\u0003אמר רב עוקבא בר חמא: תרי קשקושי הוו\u0004 \u0005[שני מיני קשקוש,\u0006 עידור, \u0005הם],\u0006 \u0003חד לאברויי אילנא\u0004 \u0005[אחד\u0006 מהם \u0005לחיזוק האילן]\u0006 \u0003ואסור, וחד לסתומי פילי ושרי\u0004 \u0005[ואחד לסיתום הסדקים ומותר]\u0006 כדי למנוע נזק. \u0003הכי נמי תרי זיהמומי הוי\u0004 \u0005[כך גם כן שני\u0006 מיני \u0005זיהום הם],\u0006 \u0003חד לאוקומי אילני ושרי\u0004 \u0005[אחד\u0006 מהם \u0005להעמיד\u0006 את \u0005האילנות ומותר],\u0006 \u0003וחד לאברויי אילני\u0004 \u0005[ואחד להבריא,\u0006 להצמיח את \u0005האילנות]\u0006 \u0003ואסור!\u0004","\u0003ואלא\u0004 תאמר כי מענין \u0003סיכה\u0004 על \u0003סיכה קא קשיא ליה\u0004 \u0005[קשה לו],\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 בברייתא: \u0003סכין שמן לגזום בין במועד ובין בשביעית, ורמינהי\u0004 \u0005[ומשליכים\u0006 על כך\u0005]\u0006 ממה ששנינו במסכת שביעית: \u0003סכין\u0004 בשמן \u0003את הפגין\u0004 התאנים שלא הבשילו, \u0003ו\u0004כן \u0003מנקבין\u0004 את הפגין, \u0003ומפטמין אותן עד ראש השנה.\u0004 ונדייק מכאן: \u0003עד ראש השנה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בשביעית\u0004 — \u0003לא!\u0004","אולם גם כאן יש לדחות: \u0003מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 כשסכים על מקום הגיזום, הסיכה מטרתה היא \u0003אוקומי אילנא, ושרי\u0004 \u0005[להעמיד את האילן\u0006 כדי שלא יינזק, \u0005ומותר],\u0006 \u0003התם\u0004 \u0005[שם]\u0006 מטרת הסיכה היא \u0003פטומי פירא\u0004 \u0005[פיטום,\u0006 השמנת \u0005הפרי],\u0006 \u0003ואסור!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב סמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אשי לרבינא:\u0004 רבה \u0003בר ירמיה,\u0004 מענין \u0003סיכה\u0004 של \u0003מועד\u0004 על \u0003זיהום\u0004 של \u0003מועד קא קשיא ליה\u0004 \u0005[קשה לו]:\u0006 \u0003מכדי האי אוקומי והאי אוקומי\u0004 \u0005[הואיל\u0006 ו\u0005זה להעמיד וזה להעמיד],\u0006 \u0003מאי שנא האי דשרי\u0004 \u0005[מה שונה זה שמותר],\u0006 \u0003ומאי שנא האי\u0004 \u0005[ומה שונה זה]\u0006 ש\u0003אסור? היינו דקאמר ליה\u0004 \u0005[זהו שאמר לו]:\u0006 \u0003לית נגר ולא בר נגר\u0004 \u0003דיפרקינה\u0004 \u0005[אין אומן ולא בן אומן שיפתור אותה].\u0006","ושבים לדון בדין משנתנו. \u0003אמר רב יהודה אמר רב: עבודה זרה שעובדין אותה במקל,\u0004 כגון שמרעישים לפניה בהכאות מקל, אם \u0003שבר מקל בפניה\u0004 — \u0003חייב,\u0004 אם \u0003זרק מקל בפניה\u0004 — \u0003פטור. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא: מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003שבר? דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003כעין זביחה,\u0004 ששבירת המקל דומה לשחיטת בהמה למקדש, והרי \u0003זרק נמי הוה ליה\u0004 \u0005[גם כן הרי הוא]\u0006 \u0003כעין זריקה\u0004 שזורקים את הדם על קרנות המזבח! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 כדי שיהיה הדבר מעין זריקת הדם \u0003בעינא\u0004 \u0005[צריכים אנו]\u0006 \u0003זריקה משתברת\u0004 שהדבר הנזרק מתחלק לטיפות, ולא בגוף אחד, \u0003וליכא\u0004 \u0005[ואין כאן].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו בברייתא: \u0003ספת\u0004 \u0005[האכיל]\u0006 \u0003לה\u0004 לעבודה זרה \u0003צואה, או שנסך לפניה עביט של מימי\u0004 \u0003רגלים,\u0004 אף שהם דברים מאוסים —"],["\u0003חייב,\u0004 אף על פי שאין זו עבודתה. \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003עביט של מימי רגלים\u0004 — \u0003איכא\u0004 \u0005[יש\u0006 בכך\u0005]\u0006 \u0003זריקה משתברת, אלא צואה, מאי\u0004 \u0005[מה]\u0006 \u0003זריקה משתברת איכא\u0004 \u0005[יש\u0006 כאן\u0005]?\u0006 ומשיבים: מדובר \u0003בצואה לחה\u0004 שמשתברת.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שיש בכך מחלוקת \u0005תנאים]\u0006 ששנינו: אם \u0003שחט לה\u0004 לעבודה זרה \u0003חגב\u0004 — \u0003ר' יהודה מחייב\u0004 משום שחיטה לעבודה זרה, \u0003וחכמים פוטרים.\u0004","\u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 שדבר שהוא \u0003כעין זביחה\u0004 חייבים עליו, כגון שוחט חגב, וכיוצא בזה השובר מקל בפניה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 שהאיסור חל כשהוא עושה \u0003כעין זביחה, אלא\u0004 דווקא כשהוא \u0003כעין פנים,\u0004 ובמקדש הרי אין זובחים חגבים?","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 שמה שהוא \u0003כעין זביחה\u0004 חייבים עליו, \u0003אלא כעין פנים בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003ו\u0004מדוע מחייב ר' יהודה במקרה זה? \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003חגב, הואיל וצוארו דומה לצואר בהמה,\u0004 ושחיטתו היא כעין שחיטה שעושים בפנים.","ובדומה למה שאמר רב יהודה בשם רב, \u0003אמר רב נחמן אמר רבה בר אבוה אמר רב: עבודה זרה שעובדין אותה במקל,\u0004 אם \u0003שבר מקל בפניה\u0004 — \u0003חייב\u0004 על המעשה, \u0003ונאסרת\u0004 תקרובת זו (המקל) בכך, \u0003זרק מקל לפניה\u0004 — \u0003חייב,\u0004 שדרכה במקל \u0003ו\u0004אולם \u0003אינה נאסרת\u0004 בכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003שבר\u0004 שחייב? \u0003דהויא ליה\u0004 \u0005[שהרי זו]\u0006 \u0003כעין זביחה\u0004 שבמקדש, ואולם \u0003זרק נמי הויא ליה\u0004 \u0005[גם כן הרי זה]\u0006 \u0003כעין זריקה\u0004 של הדם במקדש! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003זריקה משתברת\u0004 כדי לחייבו \u0003וליכא\u0004 \u0005[ואין כאן].\u0006","הקשה לו: \u0003אלא מעתה,\u0004 לפי זה, \u0003אבני בית מרקוליס במה יאסרו?\u0004 הרי אין כאן זריקה המשתברת! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אף לדידי קשיא לי\u0004 \u0005[לי\u0006 היה הדבר \u0005קשה],\u0006 \u0003ושאלתיה\u0004 את השאלה הזו \u0003לרבה בר אבוה, ורבה בר אבוה\u0004 שאל אותה \u0003לחייא בר רב, וחייא בר רב\u0004 שאל אותה \u0003לרב, ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003נעשה כמגדל עבודה זרה,\u0004 שאין כאן איסור משום תקרובת, אלא כתוספת שמוסיף לגוף העבודה זרה עצמה, שהרי האבן הופכת לחלק מגוף המרקוליס.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003עבודה זרה של גוי אסורה מיד\u0004 כשעושה אותה, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שאסורה \u0003עד שתעבד, תישתרי\u0004 \u0005[תותר]\u0006 עבודה זרה זו, \u0003דהא לא פלחה\u0004 \u0005[שהרי לא עבד אותה],\u0006 ולא הקריב לה דבר! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כל אחת ואחת\u0004 מהאבנים שהוא זורק גם \u0003נעשית עבודה זרה, ו\u0004גם נחשבת \u0003תקרובת לחברתה\u0004 לאבן המצויה שם כבר.","אמר לו: \u0003אי הכי, בתרייתא מיהא תשתרי\u0004 \u0005[אם כך,\u0006 האבן \u0005האחרונה על כל פנים תהיה מותרת],\u0006 שהרי עדיין לא הקריב לה תקרובת! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי ידעת לה, זיל שקלה\u0004 \u0005[אם אתה מכיר אותה,\u0006 את האחרונה, \u0005לך קח אותה],\u0006 שבאמת אבן זו אינה נאסרת. \u0003רב אשי אמר:\u0004 גם האבן האחרונה עצמה אסורה, שכן \u0003כל אחת ואחת\u0004 מן האבנים שזורק \u0003נעשית תקרובת לעצמה ו\u0004גם \u0003תקרובת לחברתה.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מצא בראשו\u0004 של פסל \u0003כסות ומעות או כלים\u0004 — \u0003הרי אלו מותרין,\u0004 שאינם תקרובת, אלא הניח אותן לסימן או לצורך אחר. היו בראשו \u0003פרכילי\u0004 (זמורות ועליהן אשכולות) \u0003ענבים,\u0004 או \u0003עטרות של שבלים,\u0004 או \u0003יינות, שמנים וסלתות, וכל דבר שכיוצא בו קרב לגבי מזבח\u0004 — \u0003אסור.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לגבי \u0003יינות שמנים וסלתות\u0004 — \u0003איכא\u0004 \u0005[יש כאן]\u0006 \u0003כעין פנים,\u0004 שהרי מביאים כיוצא בהם למקדש, \u0003ואיכא\u0004 \u0005[ויש כאן]\u0006 \u0003כעין זריקה משתברת, אלא פרכילי ענבים ועטרות של שבלים\u0004 — \u0003לא כעין פנים איכא\u0004 \u0005[יש\u0006 בכך\u0005],\u0006 שאין מביאים למזבח את אלה, \u0003ולא כעין זריקה משתברת איכא\u0004 \u0005[יש\u0006 בכך\u0005]!\u0006","\u0003אמר רבא אמר עולא: כגון שבצרן מתחלה לכך\u0004 לשם עבודה זרה, ומעשה בצירתן הוא כעין שחיטה, ונאסרות משום כך.","\u0003אמר ר' אבהו אמר ר' יוחנן: מנין לזובח בהמה בעלת מום לעבודה זרה שהוא פטור? שנאמר: \"זבח לאלהים יחרם בלתי לה' לבדו\"\u0004 (שמות כב, יט), \u0003לא אסרה תורה אלא כעין פנים,\u0004 והרי אין להקריב בהמה בעלת מום לגבוה.","\u0003הוי\u0004 \u0005[היה מתקשה]\u0006 \u0003בה\u0004 \u0003רבא, במאי\u0004 \u0005[במה,\u0006 באיזה מום\u0005]\u0006 מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיה בה מום \u0003בדוקין שבעין\u0004 (בכתמים שבעיניה), \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003לבני נח חזיא\u0004 \u0005[ראויה]\u0006 היא להקרבה \u0003לגבוה בבמה דידהו\u0004 \u0005[שלהם],\u0006 שאם הם רוצים להקריב קרבנות לה' באופן זה — מותר להם, \u0003לעבודה זרה מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שחייב אם הקריבה?","\u0003אלא\u0004 מתי פטור? \u0003ב\u0004שוחט \u0003מחוסר אבר, וכ\u0004דברי \u0003ר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר: מנין למחוסר אבר שהוא אסור\u0004 בהקרבה גם \u0003לבני נח? שנאמר: \"ומכל החי מכל בשר שנים מכל\"\u0004 (בראשית ו, יט), ומבעלי חיים אלה הקריב נח קרבנות לה', ו\u0003אמרה תורה:\u0004 \"מכל החי\" ללמד: \u0003הבא בהמה שחיין ראשי אברין שלה.\u0004","ושואלים: \u0003האי\u0004 \u0005[\u0006הביטוי \u0005הזה]\u0006 \u0003\"ומכל החי\" מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 לענין אחר, \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003טריפה\u0004 שלא יכניס לתיבה! ומשיבים: שדבר זה \u0003מ\"להחיות זרע\"\u0004 (ראה בראשית ז, ד) \u0003נפקא\u0004 \u0005[יוצא],\u0006 שהחיות והבהמות שמובאות צריכות להיות כאלה שיכולות להוליד.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח למי שאומר]:\u0006 \u0003טריפה אינה יולדת, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003טריפה יולדת, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי יכול להכניס טריפה מכיון שהיא יולדת!","ומשיבים: \u0003אמר קרא\u0004 \u0005[הפסוק]:\u0006 \"להחיות \u0003אתך\"\u0004 (בראשית ו, יט), כוונתו: \u0003\"אתך\"\u0004 — \u0003בדומין לך.\u0004 ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003נח גופיה\u0004 \u0005[עצמו]\u0006 \u0003טריפה הוה\u0004 \u0005[היה],\u0006 והדומים לו אף הם כך! ומשיבים: \u0003\"תמים\" כתיב ביה\u0004 \u0005[נאמר בו]\u0006 (בראשית ו, ט), משמע שהיה שלם בגופו.","ומקשים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003\"תמים\"\u0004 כוונתו שהיה תמים ושלם \u0003בדרכיו!\u0004 ומשיבים: \u0003\"צדיק\" כתיב ביה\u0004 \u0005[נאמר בו]\u0006 (בראשית ו, ט), והוא השלם בדרכיו.","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003\"תמים\"\u0004 כוונתו \u0003בדרכיו\u0004 במידותיו ובדרכי התנהגותו, \u0003ו\"צדיק\" במעשיו\u0004 הטובים! ודוחים את עיקר השאלה: \u0003לא מצית אמרת\u0004 \u0005[אינך יכול לומר]\u0006 ש\u0003נח גופיה\u0004 \u0005[עצמו]\u0006 \u0003טריפה הוה\u0004 \u0005[היה],\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 ש\u0003נח טריפה הוה\u0004 \u0005[היה],\u0006 וכי \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רחמנא\u0004 \u0005[הקדוש ברוך הוא]:\u0006 \u0003דכוותך עייל, שלמין לא תעייל\u0004 \u0005[כמותך הכנס\u0006 לתיבה, \u0005ושלמים אל תכניס]?\u0006","ושואלים: \u0003השתא דנפקא\u0004 \u0005[עכשיו, שיצא]\u0006 הענין הזה של טריפה שפסולה להקרבה \u0003מ\u0004מה שכתוב \u0003\"אתך\",\u0004 הפסוק \u0003\"להחיות זרע\" למה לי?\u0004 למה נאמר? ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004הפסוק \u0003\"אתך\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003לצוותא בעלמא\u0004 \u0005[לחברה בלבד],\u0006 ואינו צריך להקפיד, \u0003ואפילו\u0004 \u0003זקן ואפילו סריס\u0004 שאינם מתרבים יכניס לשם (כל עוד אינו טריפה), \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שצריך להיות כזה שיכול \u0003להחיות זרע\u0004 ולהוליד.","\u0003אמר ר' אלעזר: מנין לשוחט בהמה למרקוליס שהוא חייב,\u0004 אף על פי שאין דרכו לזבוח לו זבחי בהמות? \u0003שנאמר: \"ולא יזבחו עוד את זבחיהם לשעירם\"\u0004 (ויקרא יז, ז), \u0003אם אינו ענין ל\u0004עבודה זרה שעובדים \u0003כדרכה\u0004 של אותה עבודה זרה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שלא יאמרו ישראל: \u0003\"איכה יעבדו הגוים האלה את אלהיהם\u0004 ואעשה כן גם אני\" (דברים יב, ל), ולכן אם דרכה בזביחה אסורה מטעם זה, \u0003תנהו ענין\u0004 לזביחה שעושים לכבודו \u0003לשלא כדרכה.\u0004","ושואלים: \u0003והא להכי\u0004 \u0005[ו\u0006פסוק \u0005זה ל\u0006צורך \u0005כך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]?\u0006 \u0003האי מיבעי ליה לכדתניא\u0004 \u0005[זה נחוץ לו לכמו ששנויה\u0006 בברייתא\u0005]\u0006 בפרשת איסור שחיטת קדשים מחוץ למשכן:"],["\u0003עד כאן\u0004 עד הפסוק שיוזכר להלן, \u0003הוא מדבר\u0004 בפרשה זו \u0003בקדשים שהקדישן בשעת איסור הבמות\u0004 לאחר שהוקם המשכן, \u0003והקריבן בשעת איסור הבמות,\u0004","\u0003שהרי עונשן אמור, שנאמר: \"ואל פתח אהל מועד לא הביאו...\u0004 ונכרת האיש ההוא מקרב עמו\" \u0003וגו'\u0004 (ויקרא יז, ד). ומוסיפים: \u0003עונש\u0004 על כך \u0003שמענו, אזהרה מנין? תלמוד לומר:\u0004 \"השמר לך \u0003פן תעלה עלתיך\u0004 בכל מקום אשר תראה\" (דברים יב, יג),","ומסבירה הגמרא: \u0003ו\u0004הוא \u0003כ\u0004דברי\u0003 ר' אבין אמר ר' אילא,\u0004 ש\u0003אמר ר' אבין אמר ר' אילא: כל מקום שנאמר \"השמר\"\u0004 או \u0003\"פן\"\u0004 או \u0003\"אל\"\u0004 — \u0003אינו אלא ב\u0004איסור \u0003לא תעשה,\u0004 אף על פי שלא נאמר במפורש \"לא\".","וממשיכה הברייתא: \u0003מכאן ואילך הוא\u0004 הכתוב \u0003מדבר בקדשים שהקדישן בשעת היתר הבמות\u0004 לפני בנין המשכן \u0003והקריבן בשעת איסור הבמות,\u0004 שהוא מצווה להביאם למשכן,","\u0003שנאמר: \"למען אשר יביאו בני ישראל את זבחיהם אשר הם זבחים\"\u0004 (ויקרא יז, ה), כלומר זבחים \u0003שהתרתי לך כבר,\u0004 שהיו רגילים לזבוח קודם לכן בכל מקום. ומה שנאמר: \u0003\"על פני השדה\"\u0004 (ויקרא יז, ה) — \u0003מלמד שכל הזובח בבמה בשעת איסור הבמות, מעלה עליו הכתוב כאילו הוא זובח על פני השדה\u0004 לעבודה זרה.","\u0003\"והביאם לה'\"\u0004 (ויקרא יז, ה) — \u0003זו מצות עשה\u0004 להביא גם קרבנות אלו למשכן. \u0003ומצות לא תעשה\u0004 שיש בכך \u0003מנין? תלמוד לומר: \"ולא יזבחו עוד את זבחיהם\"\u0004 (ויקרא יז, ז).","\u0003יכול יהא ענוש כרת\u0004 על כך? \u0003תלמוד לומר: \"חקת עולם תהיה זאת להם\"\u0004 (ויקרא יז, ח), \u0003זאת להם\u0004 — מצות עשה ואיסור לא תעשה, \u0003ולא אחרת להם\u0004 כלומר, לא יחול עליהם עונש הכרת האמור במי שהקדיש את קרבנו בשעת איסור הבמות. ועל כל פנים, נמצא שאנו למדים מן הכתוב \"ולא יזבחו\" ענין אחר לגמרי, ולא לענין איסור זביחה לעבודה זרה, כדברי ר' אלעזר!","\u0003אמר רבא:\u0004 יש ללמוד מן הביטוי \"ולא יזבחו עוד\" שני עניינים, \u0003קרי ביה\u0004 \u0005[קרא בו]\u0006 בפסוק זה: \u0003\"ולא יזבחו\", וקרי ביה\u0004 \u0005[וקרא בו\u0006 גם\u0005]:\u0006 \u0003\"ולא עוד\",\u0004 ש\"לא\" זה משמש לשני עניינים: לענין שלא יזבחו בזמן איסור הבמות, ועוד לענין האיסור שיש בזביחת בהמה לעבודה זרה, אפילו שלא כדרך עבודתה.","\u0003מצא בראשו\u0004 של מרקוליס \u0003מעות,\u0004 או \u0003כסות או כלים\u0004 — \u0003הרי אלו מותרין.\u0004 אם מצא שם \u0003פרכילי ענבים,\u0004 זמורות ועליהם אשכולות של ענבים, או \u0003עטרות של שבלים,\u0004 או \u0003יינות ושמנים וסלתות, וכל דבר שכיוצא בו קרב על גבי המזבח\u0004 — \u0003אסור.\u0004","על מה ששנינו במשנה שאם מצא בראשו של מרקוליס מעות או כסות וכלים אינם אסורים, שואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב חייא בר יוסף אמר ר' אושעיא, כתוב אחד אומר: \"ותראו את שקוציהם ואת גלליהם עץ ואבן כסף וזהב אשר עמהם\"\u0004 (דברים כט, טז), \u0003וכתוב אחד אומר: \"לא תחמד כסף וזהב עליהם\"\u0004 (דברים ז, כה), \u0003הא כיצד\u0004 בכתוב אחד (\"אשר עמהם\") נאמר גם עץ ואבן, ובשני נאמר רק כסף וזהב (\"אשר עליהם\")?","יש להסביר כי בא הדבר ללמד שהאיסור של מה ש\u0003\"עמהם\"\u0004 כלומר, מה שנמצא ליד עבודה זרה, הריהו \u0003דומיא\u0004 \u0005[דומה]\u0006 לאיסור של מה ש\u0003\"עליהם\", מה \"עליהם\"\u0004 — הוא \u0003דבר של נוי\u0004 (כסף וזהב) ודווקא הוא \u0003אסור,\u0004 אבל דבר \u0003שאינו של נוי מותר, אף \"עמהם\"\u0004 מה שמצוי לידם — דווקא \u0003דבר של נוי אסור, ושאינו של נוי מותר.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 להיפך: \u0003\"עליהם\" דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003\"עמהם\", מה \"עמהם\"\u0004 — כוונתו \u0003כל מה שעמהם\u0004 אף עץ ואבן, \u0003אף \"עליהם\"\u0004 — \u0003כל\u0004 מה \u0003שעליהם!\u0004 ומשיבים: \u0003אם כן, לא יאמר\u0004 בכלל את הפסוק הזה \u0003\"עליהם\",\u0004 שהרי אם מה שלידם נאסר — קל וחומר מה שעליהם ממש. אלא יש ללמוד מכאן בהכרח שרק דבר שהוא של נוי אסור.","ומקשים: והרי \u0003מעות\u0004 שבמשנתנו \u0003דבר של נוי הוא,\u0004 והם מותרים אם נמצאו על מרקוליס! \u0003אמרי דבי\u0004 \u0005[אומרים\u0006 על כך \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 לא מדובר שם כשהיו עליו מעות לנוי, אלא \u0003בכיס\u0004 של מעות \u0003קשור ותלוי לו בצוארו,\u0004 ומכאן שלא נעשו לקישוט, אלא כדי לשומרם שם, או כשכר לכמרים.","ועוד מקשים: \u0003כסות\u0004 שהתירו במשנה, הלוא \u0003דבר של נוי הוא! אמרי דבי\u0004 \u0005[אומרים בבית מדרשו]\u0006 של \u0003ר' ינאי:\u0004 לא מדובר בכסות שלבוש בה הפסל, אלא \u0003בכסות מקופלת ומונחת לו על ראשו.\u0004 ועוד שואלים: \u0003כלי\u0004 שהותר במשנה, הלוא \u0003דבר של נוי הוא! אמר רב פפא:\u0004 הכוונה היא \u0003דסחיפא ליה משכילתא ארישיה\u0004 \u0005[שהפוכה לו קדירה על ראשו],\u0006 שזה ודאי אינו דבר של נוי.","\u0003אמר רב אסי בר חייא: כל שהוא לפנים מן הקלקלין\u0004 כלומר, מן המחיצה הפנימית של העבודה הזרה — \u0003אפילו\u0004 היו שם \u0003מים ומלח אסור,\u0004 שוודאי לשם תקרובת עבודה זרה הם שם, והנמצא \u0003חוץ לקלקלין\u0004 — \u0003דבר של נוי אסור, שאינו של נוי מותר. אמר ר' יוסי בר חנינא, נקטינן\u0004 \u0005[מוחזקים אנו]\u0006 ש\u0003אין\u0004 דין \u0003קלקלין לא לפעור ולא למרקוליס.\u0004","ושואלים: \u0003למאי\u0004 \u0005[למה]\u0006 לאיזה ענין נאמר הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003אפילו\u0004 מה שהוא ל\u0003פנים\u0004 מן הקלקלין \u0003כחוץ דמי\u0004 \u0005[נחשב],\u0006 \u0003ו\u0004גם הוא \u0003שרי\u0004 \u0005[מותר]\u0006 אם אינו של נוי, כגון מים ומלח — הדבר תמוה, שכן \u0003השתא פעורי מפערין קמיה\u0004 \u0005[עכשיו,\u0006 הרי \u0005מפערים בפניו\u0006 בצואה\u0005],\u0006 \u0003מים ומלח לא מקרבין ליה\u0004 \u0005[מקריבים לו]?\u0006 \u0003אלא\u0004 ודאי צריך לפרש להיפך: בפעור ומרקוליס \u0003אפילו חוץ כבפנים דמי\u0004 \u0005[נחשב]\u0006 \u0003ואסור\u0004 כל דבר, שכל דבר נחשב לעבודה זרה זו כדבר של נוי.","\u0003עבודה זרה שהיה לה גינה או מרחץ\u0004 — \u0003נהנין מהן שלא בטובה\u0004 כלומר, בזמן שאינו משלם שכר לעבודה זרה, \u0003ואין נהנין מהן בטובה. היה\u0004 המרחץ או הגינה \u0003שלה ושל אחרים\u0004 — \u0003נהנין מהן בין בטובה ובין שלא בטובה.\u0004 ובענין אחר: פסל או צורה של \u0003עבודה זרה של נכרי\u0004 — \u0003אסורה מיד\u0004 כשעשאוה לצורך זה, \u0003ושל ישראל\u0004 — \u0003אין אסורה עד שתיעבד\u0004 בפועל.","\u0003אמר אביי:\u0004 מה שאמרו שאסור ליהנות מן הגינה או מרחץ של עבודה זרה \u0003בטובה\u0004 — כוונתו \u0003בטובת כומרין\u0004 שמעלה להם שכר, \u0003שלא בטובה\u0004 — \u0003שלא בטובת כומרין; לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003טובת עובדיה\u0004 של עבודה זרה זו, שאינם כמרים אלא רק עובדים אותה סתם, \u0003דשרי\u0004 \u0005[שמותר]\u0006 ליהנות מהם בשכר.","\u0003איכא דמתני לה אסיפא\u0004 \u0005[יש ששונה\u0006 את דברי אביי \u0005על סופה\u0006 של המשנה\u0005]:\u0006 \u0003היה שלה ושל אחרים\u0004 — \u0003נהנין מהן בטובה ושלא בטובה. אמר אביי: בטובה\u0004 — כוונתו \u0003בטובת אחרים, שלא בטובה\u0004 — \u0003שלא בטובת כומרין,\u0004 אבל בטובת כומרים — אסור.","ומעירים: \u0003מאן דמתני אסיפא\u0004 \u0005[מי ששונה\u0006 את דברי אביי \u0005על הסוף]\u0006 שאם היה שלה ושל אחרים אסור בטובת כומרים — \u0003כל שכן\u0004 שהוא שונה \u0003ארישא\u0004 \u0005[על ראשה],\u0006 כשכולה של עבודה זרה. \u0003ומאן דמתני ארישא\u0004 \u0005[ומי ששונה על ראשה]\u0006 — דווקא שם אסור, \u0003אבל אסיפא\u0004 \u0005[על סופה],\u0006 \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003אחרים בהדה\u0004 \u0005[יחד איתה],\u0006 \u0003אפילו בטובת כומרין נמי שפיר דמי\u0004 \u0005[גם כן מותר הדבר].\u0006","שנינו במשנה: \u0003עבודה זרה של נכרי אסורה מיד.\u0004 ומעירים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' עקיבא היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"אבד תאבדון את כל המקמות אשר עבדו שם הגוים\"\u0004 (דברים יב, ב), \u0003בכלים שנשתמשו בהן\u0004 הגוים \u0003לעבודה זרה הכתוב מדבר.\u0004","\u0003יכול עשאום\u0004 לשם עבודה זרה \u0003ולא גמרום, גמרום ולא הביאום, הביאום ולא נשתמשו בהן, יכול יהו אסורים? תלמוד לומר: \"אשר עבדו שם הגוים\",\u0004 לומר \u0003שאין אסורין עד שיעבדו; מכאן אמרו: עבודה זרה של נכרי\u0004 — \u0003אינה אסורה עד שתיעבד, ושל ישראל\u0004 — \u0003אסורה מיד,\u0004 אלו \u0003דברי ר' ישמעאל.\u0004","\u0003ר' עקיבא אומר, חילוף הדברים: עבודה זרה של נכרי\u0004 — \u0003אסורה מיד, ושל ישראל\u0004 — אינה אסורה \u0003עד שתיעבד,\u0004 ומשנתנו היא, איפוא, כשיטת ר' עקיבא. ודנים בגופה של אותה ברייתא.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בכלים שנשתמשו בהן לעבודה זרה הכתוב מדבר.\u0004 ומקשים: \u0003הא \"מקומות\" כתיב\u0004 \u0005[נאמר]\u0006 בכתוב, ולא כלים! ומשיבים: \u0003אם אינו ענין למקומות, דלא מיתסרי\u0004 \u0005[שאין\u0006 המקומות עצמם \u0005נאסרים],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אלהיהם על ההרים\"\u0004 (דברים יב, ב), ומכאן אנו מדייקים: \u0003ולא ההרים אלהיהם,\u0004 שאין ההרים נאסרים,"],["אם כן \u0003תנהו ענין לכלים\u0004 המשמשים לעבודה זרה. בהמשך הברייתא שנינו, \u0003מכאן אמרו: עבודה זרה של נכרי אינה אסורה אלא עד שתעבד, ושל ישראל\u0004 נאסרת \u0003מיד.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בכלים אוקימנא לה\u0004 \u0005[העמדנו אותה],\u0006 המשמשים את העבודה זרה, ולא בפסילי עבודה זרה עצמה! ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אשר אתם ירשים אתם את אלהיהם\"\u0004 (דברים יב, ב), \u0003מקיש\u0004 (משוה) כתוב זה \u0003אלהיהם לכלים, מה כלים\u0004 אינם אסורים \u0003עד שיעבדו, אף אלהיהם נמי\u0004 \u0005[גם כן]\u0006 אינם אסורים \u0003עד שיעבדו.\u0004 ומן הצד האחר: \u0003ור' עקיבא דלא מקיש\u0004 \u0005[שאינו משווה]\u0006 בין הדברים, שהרי לשיטתו עבודה זרה של נכרי אסורה מיד, \u0003אמר לך\u0004 \u0005[\u0006יכול \u0005לומר לך]:\u0006 \u0003\"את\"\u0004 שנאמר שם \u0003הפסיק הענין,\u0004 לחלק בין \"ההרים\" (כלומר, הכלים) ובין \"אלהיהם\".","ועוד לבירור השיטות, שואלים: \u0003ור' ישמעאל, אשכחן\u0004 \u0005[מצאנו]\u0006 ש\u0003עבודה זרה של נכרי\u0004 ש\u0003אינה אסורה עד שתעבד,\u0004 אבל של \u0003ישראל\u0004 ש\u0003אסורה מיד מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003סברא הוא\u0004 \u0005[סברה היא\u0006 זו\u0005],\u0006 ממה שעבודה זרה של \u0003נכרי\u0004 אינה נאסרת \u0003עד שתעבד,\u0004 מכאן שזו של \u0003ישראל אסורה מיד.\u0004 ומקשים: \u0003אימא\u0004 \u0005[אמור]:\u0006 של \u0003ישראל כלל וכלל לא\u0004 תיאסר! ודוחים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003גניזה בעיא\u0004 \u0005[צריכה\u0006 היא\u0005]\u0006 עבודה זרה של ישראל, ואין לה ביטול, וכי \u0003איתסורי לא מיתסרא\u0004 \u0005[להיאסר אינה נאסרת]?\u0006","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 עבודה זרה זו של ישראל יהא דינה כמו של \u0003נכרי!\u0004 ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואת חטאתכם אשר עשיתם את העגל\"\u0004 (דברים ט, כא), לומר ש\u0003משעת עשייה קם ליה\u0004 \u0005[עמד לו]\u0006 \u0003בחטא.\u0004","ודוחים: \u0003אימא\u0004 \u0003הני מילי למיקם גברא\u0004 \u0005[אמור\u0006 ש\u0005דברים אלה\u0006 אמורים כדי \u0005שיעמוד האיש]\u0006 \u0003בחטא,\u0004 שמיד שעשה צלם לעבודה זרה הריהו חוטא, אבל \u0003איתסורי לא מיתסרא\u0004 \u0005[\u0006היא עצמה \u0005להיאסר אינה נאסרת]!\u0006 ומשיבים, \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ארור האיש אשר יעשה פסל ומסכה\"\u0004 (דברים כז, טו), לומר: \u0003משעת עשייה קם ליה\u0004 \u0005[עומד הוא]\u0006 \u0003ב\"ארור\".\u0004","ומקשים: גם כאן, \u0003אימא הני מילי למיקם גברא\u0004 \u0005[אמור\u0006 ש\u0005דברים אלה\u0006 אמורים \u0005שיעמוד האיש]\u0006 \u0003ב\"ארור\",\u0004 אבל \u0003איתסורי לא מיתסרא\u0004 \u0005[\u0006היא עצמה \u0005להיאסר אינה נאסרת]!\u0006 ומשיבים: \u0003\"תועבת ה'\" כתיב\u0004 \u0005[נאמר]\u0006 (דברים כז, טו), משמע שהיא עצמה תועבה ואסורה.","ושואלים: \u0003ור' עקיבא,\u0004 שסבור שאינה נאסרת מיד, כיצד הוא מפרש כתוב זה? לדעתו הכוונה היא שעושה \u0003דבר המביא לידי תועבה\u0004 כלומר, לידי עבודה זרה, אבל אין ללמוד מכאן שהיא עצמה קרויה כך מתחילתה.","ומבררים את שיטת ר' עקיבא: \u0003ור' עקיבא, עבודה זרה של נכרי\u0004 ש\u0003אסורה מיד מנא ליה\u0004 \u0005[מנין לו]?\u0006 \u0003אמר עולא, אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"פסילי אלהיהם תשרפון באש\"\u0004 (דברים ז, כה), לומר: מיד \u0003משפסלו נעשה אלוה.\u0004","ומן הצד האחר, \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' ישמעאל\u0005]\u0006 כיצד הוא מפרש פסוק זה? \u0003ההוא מיבעי ליה לכדתני\u0004 \u0005[אותו\u0006 פסוק \u0005נצרך לו לכמו ששנה]\u0006 \u0003רב יוסף, דתני\u0004 \u0005[ששנה]\u0006 \u0003רב יוסף: מנין לגוי שפוסל אלוהו\u0004 שיכול לבטלו? \u0003שנאמר: \"פסילי אלהיהם תשרפון באש\".\u0004","ומן הצד השני, \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' עקיבא\u0005]\u0006 מנין לומד הוא דבר זה? \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 \u0003מ\u0004מה שאמר \u0003שמואל,\u0004 ש\u0003שמואל רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"לא תחמד כסף וזהב עליהם\"\u0004 (דברים ז, כה), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בהמשך: \u0003\"ולקחת לך\"\u0004 (דברים ז, כה), שרשאי אתה לקחת, \u0003הא כיצד?\u0004 אם \u0003פסלו\u0004 הנכרי \u0003לאלוה\u0004 — \u0003\"לא תחמד\"\u0004 ולא תקח, לפי שהוא נאסר מיד, אם \u0003פסלו מאלוה\u0004 וביטלו — הרי בזה אפשר לקיים \u0003\"ולקחת לך\".\u0004","ושואלים עוד: \u0003ור' עקיבא, אשכחן\u0004 \u0005[מצאנו]\u0006 מקור לכך ש\u0003עבודה זרה של נכרי\u0004 ש\u0003אסורה מיד,\u0004 של \u0003ישראל\u0004 שאינה אסורה \u0003עד שתעבד מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אמר רב יהודה, אמר קרא\u0004 \u0005[המקרא]:\u0006 \"ארור האיש אשר יעשה פסל ומסכה... \u0003ושם בסתר\"\u0004 (דברים כז, טו), \u0003עד שיעשה לה דברים שבסתר\u0004 כלומר, שיעבוד אותה.","ומן הצד האחר, \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' ישמעאל\u0005]\u0006 כיצד הוא מפרש את הדבר? \u0003ההוא מיבעיא ליה\u0004 \u0005[אותו\u0006 פסוק \u0005נצרך לו]\u0006 \u0003ל\u0004כמו שאמר \u0003ר' יצחק,\u0004 ש\u0003אמר ר' יצחק: מנין לעבודה זרה של ישראל שטעונה גניזה? שנאמר: \"ושם בסתר\"\u0004 כלומר, צריכים לשים אותה במקום נסתר, בגניזה.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' עקיבא\u0005]\u0006 מנין לומד הוא דבר זה? \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 \u0003מ\u0004מה שאמר \u0003רב חסדא אמר רב,\u0004 ש\u0003אמר רב חסדא אמר רב: מנין לעבודה זרה של ישראל שטעונה גניזה? שנאמר: \"לא תטע לך אשרה כל עץ אצל מזבח\u0004 ה' אלהיך\" (דברים טז, כא), ללמד: \u0003מה מזבח טעון גניזה, אף אשרה טעונה גניזה.\u0004","\u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' ישמעאל\u0005]\u0006 מה הוא לומד מפסוק זה? \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 פסוק \u0005נצרך לו]\u0006 \u0003ל\u0004כמו שאמר \u0003ריש לקיש,\u0004 ש\u0003אמר ריש לקיש: כל המעמיד\u0004 (הממנה) \u0003דיין שאינו הגון\u0004 (מצד בערותו או רשעתו) — \u0003כאילו נוטע אשרה בישראל, שנאמר: \"שפטים ושטרים תתן לך בכל שעריך\"\u0004 (דברים כז, יח), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 הכתוב: \u0003\"לא תטע לך אשרה כל עץ\"\u0004 (דברים כז, כא).","\u0003אמר רב אשי: ובמקום\u0004 שיש \u0003תלמידי חכמים,\u0004 אם הוא מעמיד דיין שאינו הגון — \u0003כאילו נטעו\u0004 לעץ אשרה \u0003אצל מזבח\u0004 ה', \u0003שנאמר: \"אצל מזבח\".\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב המנונא: ריתך כלי\u0004 שבור ותיקנו \u0003לעבודה זרה, מהו?\u0004 ושואלים: \u0003עבודה זרה דמאן\u0004 \u0005[של מי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003עבודה זרה\u0004 של \u0003נכרי,\u0004 הלוא \u0003בין לר' ישמעאל ובין לר' עקיבא\u0004 הכלים הללו \u0003משמשי עבודה זרה הן, ומשמשי עבודה זרה אין אסורין עד שיעבדו\u0004 בהם בפועל! \u0003אלא\u0004 בהכרח מדובר ב\u0003עבודה זרה\u0004 של \u0003ישראל,\u0004 ואולם עדיין יש לברר:","\u0003אליבא דמאן\u0004 \u0005[לפי שיטת מי]?\u0006 \u0003אילימא אליבא\u0004 \u0005[אם תאמר לפי שיטת]\u0006 \u0003ר' עקיבא, השתא היא גופה לא מיתסרא\u0004 \u0005[עכשיו,\u0006 הרי \u0005היא עצמה אינה אסורה]\u0006 \u0003עד שתעבד\u0004 בפועל, \u0003משמשיה מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאינם אסורים? \u0003ואלא\u0004 תאמר כי השאלה היא \u0003אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' ישמעאל\u0004 ש\u0003אמר:\u0004 עבודה זרה של ישראל \u0003אסורה מיד,\u0004 וכך הוא שואל:","\u0003מאי\u0004 \u0005[מה]\u0006 יהיה הדין במשמשיה? האם \u0003משמשין ממשמשין גמרינן\u0004 \u0005[אנו למדים],\u0006 \u0003מה התם\u0004 \u0005[שם]\u0006 בשל גוי אינם אסורים \u0003עד שיעבדו\u0004 בפועל, \u0003אף הכא\u0004 \u0005[כאן]\u0006 בשל ישראל אינם נאסרים \u0003עד שיעבדו, או דלמא מינה גמר\u0004 \u0005[שמא ממנה\u0006 עצמה הוא \u0005לומד],\u0006 מעבודה זרה של ישראל, \u0003מה היא\u0004 עצמה \u0003אסורה מיד אף משמשיה אסורין מיד?\u0004","גם זאת יש לדחות: אם זו היא השאלה של רב המנונא, \u0003מאי איריא דקא מיבעיא ליה\u0004 \u0005[מה שייך,\u0006 מדוע דווקא \u0005נשאלה לו\u0006 השאלה\u0005]\u0006 ב\u0003ריתך כלי? תיבעי ליה\u0004 \u0005[\u0006ש\u0005תישאל לו\u0006 השאלה\u0005]\u0006 ב\u0003עשה\u0004 כלי לצורך זה מתחילה!","ומשיבים: \u0003רב המנונא\u0004 עוסק בכלי ששימש כבר לעבודה זרה ונשבר, ו\u0003משום טומאה ישנה קמיבעיא ליה\u0004 \u0005[נשאלה לו\u0006 השאלה\u0005],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כלי מתכות,\u0004 בין \u0003פשוטיהן\u0004 כלומר, בין שהם כלים בלי בית קיבול, \u0003ו\u0004בין \u0003מקבליהן\u0004 שיש בהם כלי קיבול, אם נגעה בהם טומאה — הרי הם \u0003טמאין,\u0004 אם \u0003נשתברו\u0004 — \u0003טהרו,\u0004 אם \u0003חזר ועשאן\u0004 מן השברים הללו \u0003כלים\u0004 — \u0003יחזרו לטומאה ישנה;\u0004","\u0003והכי קמיבעיא ליה\u0004 \u0005[וכך נשאלה לו\u0006 השאלה\u0005]:\u0006 \u0003כי הדרא\u0004 \u0005[כאשר חוזרת]\u0006 \u0003טומאה\u0004 לכלים, כגון על ידי ריתוך — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 להחזיר את הטומאה בכלים הללו \u0003לטומאה דאורייתא\u0004 \u0005[שמן התורה]\u0006 שהיתה בהם, \u0003אבל טומאה דרבנן\u0004 \u0005[של דברי סופרים]\u0006 — \u0003לא,\u0004 וטומאת עבודה זרה היא רק מדברי סופרים, \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]?\u0006 ושואלים: \u0003ותיבעי ליה\u0004 \u0005[ושתשאל לו\u0006 השאלה\u0005]\u0006 ב\u0003שאר טומאות דרבנן\u0004 \u0005[מדברי סופרים],\u0006 מדוע שאל דווקא לענין עבודה זרה?","ומשיבים: \u0003חדא מגו חדא קמיבעיא ליה\u0004 \u0005[אחת מתוך אחת נשאלה לו],\u0006 כלומר שאל שאלה אחת הנובעת משאלה אחרת, וכך יש להבין את השאלה: \u0003טומאה דרבנן\u0004 \u0005[שמדברי סופרים]\u0006 \u0003מי הדרא\u0004 \u0005[האם\u0006 היא \u0005חוזרת]\u0006 \u0003או לא הדרא\u0004 \u0005[חוזרת]?\u0006 \u0003אם תימצי לימא\u0004 \u0005[תמצא לומר]\u0006 \u0003לא הדרא\u0004 \u0005[אינה חוזרת],\u0006 \u0003טומאה\u0004 של \u0003עבודה זרה, משום חומרא\u0004 של \u0003עבודה זרה מי שויוה רבנן כטומאה דאורייתא\u0004 \u0005[האם עשו אותה חכמים כטומאה שמן התורה]\u0006 \u0003או לא?\u0004 שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעי מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' יוחנן מר' ינאי: תקרובת עבודה זרה של אוכלים,\u0004 שמביא אוכלים כתקרובת, \u0003מהו\u0004 \u0005[מה]\u0006 דינם? \u0003מי מהניא להו\u0004 \u0005[האם מועיל להם]\u0006 \u0003ביטול\u0004 שמבטל אותם הגוי, \u0003לטהרינהו\u0004 \u0005[לטהר אותם]\u0006 \u0003מטומאה\u0004 שהטילו חכמים על תקרובת עבודה זרה, \u0003או לא?\u0004","ושואלים: \u0003ותיבעי ליה\u0004 \u0005[ושתישאל לו\u0006 השאלה\u0005]\u0006 לגבי \u0003כלים\u0004 של עבודה זרה, האם נטהרו כשביטלם! ומשיבים: ב\u0003כלים לא קמיבעיא ליה\u0004 \u0005[נשאלה לו\u0006 השאלה\u0005],\u0006 ומדוע? \u0003כיון דאית להו\u0004 \u0005[שיש להם]\u0006 אפשרות של \u0003טהרה במקוה\u0004 — \u0003טומאה נמי\u0004 \u0005[גם כן]\u0006 \u0003בטלה\u0004 כאשר מבטל אותם, \u0003כי קמיבעיא ליה\u0004 \u0005[כאשר נשאלה לו\u0006 השאלה\u0005]\u0006 — הרי זה ב\u0003אוכלין,\u0004 שאינם נטהרים במקוה, האם טומאה שהיתה בהם בטילה כשהוא מבטלם מלהיות תקרובת.","ושואלים: \u0003ותיבעי ליה\u0004 \u0005[ושתשאל לו\u0006 השאלה\u0005]\u0006 ב\u0003עבודה זרה גופה\u0004 \u0005[עצמה],\u0006 כגון שעשה עבודה זרה מאוכלים! ומשיבים: \u0003עבודה זרה גופה\u0004 \u0005[עצמה]\u0006 \u0003לא מיבעיא ליה\u0004 \u0005[נשאלה לו],\u0006"],["\u0003כיון\u0004 ש\u0003איסורה בטיל\u0004 על ידי שמבטל אותה, \u0003טומאה נמי\u0004 \u0005[גם כן]\u0006 \u0003בטלה. כי קא מיבעיא ליה\u0004 \u0005[כאשר נשאלה לו\u0006 השאלה הזו\u0005]\u0006 הרי זה ב\u0003תקרובת לעבודה זרה\u0004 שהיא \u0003של אוכלין, מאי\u0004 \u0005[מה]\u0006 הדין? וצדדי השאלה, \u0003כיון דאיסוריה לא בטיל\u0004 \u0005[שאיסורו אינו בטל],\u0006 \u0003כ\u0004דברי \u0003רב גידל,\u0004 שאמר שאין תקרובת עבודה זרה בטילה מאיסורה לעולם, אם כן נאמר ש\u0003טומאה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא בטלה, או דלמא\u0004 \u0005[שמא]\u0006 \u0003איסור\u0004 של תקרובת עבודה זרה שהוא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003לא בטיל,\u0004 אבל \u0003טומאה דרבנן\u0004 \u0005[שחכמים\u0006 גזרו\u0005]\u0006 \u0003בטיל\u0004 \u0005[בטילה]?\u0006 שאלה זו לא נפתרה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' יוסי בן שאול מרבי: כלים ששימשו בהן\u0004 לעבודה זרה \u0003בבית חוניו\u0004 שהיה מקדש שהקימו יהודים במצרים, \u0003מהו\u0004 דינם לענין \u0003שישתמשו בהן בבית המקדש?\u0004","ומעירים: \u0003וקא מיבעיא ליה\u0004 \u0005[ונשאלה לו\u0006 השאלה\u0005]\u0006 \u0003אליבא דמאן דאמר\u0004 \u0005[לדעת מי שאומר]\u0006 ש\u0003בית חוניו לאו בית עבודה זרה היא,\u0004 אלא מקום לעבודת ה', אלא שעברו על איסור להקריב קרבנות מחוץ למקדש, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כהנים ששימשו\u0004 (שעבדו) \u0003בבית חוניו לא ישמשו במקדש שבירושלים, ואינו צריך לומר\u0004 שלא ישמשו במקדש כהנים ששימשו \u0003לדבר אחר\u0004 כלומר, לעבודה זרה. ומכאן שבית חוניו עצמו אינו בית עבודה זרה.","וכך היא השאלה של ר' יוסי בן שאול: דווקא \u0003כהנים הוא דקנסינהו רבנן\u0004 \u0005[שקנסו אותם חכמים]\u0006 שלא יעבדו במקדש, \u0003משום\u0004 ש\u0003בני דעה נינהו\u0004 \u0005[הם],\u0006 ועברו על איסור, \u0003אבל כלים\u0004 שאינם בני דעה — \u0003לא,\u0004 שאין מקום לגזור עליהם, \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]\u0006 דינם של כלים מדינם של כהנים, ואף עליהם גזרו?","\u0003אמר לו\u0004 רבי לר' יוסי בן שאול: \u0003אסורים הן\u0004 כלים אלה, \u0003ומקרא היה בידינו\u0004 המוכיח דבר זה \u0003ושכחנוהו.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' יוסי בן שאול ממה שאמרו הכהנים לחזקיהו מלך יהודה לאחר שטיהרו את המקדש מטומאות אביו אחז: \u0003\"כל הכלים\u0004 (של בית המקדש) \u0003אשר הזניח המלך אחז במלכותו במעלו\u0004 (שעבד עבודה זרה) \u0003הכנו והקדשנו\u0004 והנם לפני מזבח ה' \" (דברי הימים ב כט, יט), \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הפירוש: \u0003\"הכנו\"\u0004 — \u0003דאטבלינהו\u0004 \u0005[שהטבלנו אותם],\u0006 \u0003\"הקדשנו\"\u0004 — \u0003דאקדישננהו\u0004 \u0005[שהקדשנו אותם],\u0006 משמע שאפשר להשתמש בהם לעבודת המקדש למרות שנעשה בהם איסור!","\u0003אמר לו\u0004 רבי: \u0003ברוך אתה לשמים שהחזרת לי אבדתי\u0004 כלומר, אתה גרמת לי להיזכר בדבר ששכחתי, כי זה היה באמת הפסוק שממנו שמעתי להיפך, שהם אסורים, שכך יש להבין את הנאמר בו: \u0003\"הכנו\"\u0004 — כוונתו \u0003שגנזנום, ו\"הקדשנו\"\u0004 — כוונתו \u0003שהקדשנו אחרים תחתיהם,\u0004 כיון שהם עצמם אסורים.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 כי \u0005מסייע לו\u0006 לרבי\u0005]\u0006 מה ששנינו: לשכה \u0003מזרחית צפונית\u0004 שבבית המוקד שבעזרה — \u0003בה גנזו בית חשמונאי את אבני המזבח ששקצו אנשי יון, ואמר רב ששת:\u0004 הכוונה היא \u0003ששקצו\u0004 את האבנים \u0003לעבודה זרה,\u0004 משמע שדברים של המקדש שהשתמשו בהם לעבודה זרה — אין להם תקנה אלא גניזה!","\u0003אמר רב פפא:\u0004 אין משם סיוע לשאלה האם קונסים חכמים ואוסרים לשמש בכלי שרת שעשו בהם איסור, שכן \u0003התם\u0004 \u0005[שם]\u0006 בענין זה \u0003קרא אשכח ודרש\u0004 \u0005[מקרא מצאו ודרשו]\u0006 שהמזבח נתחלל מקדושתו, ולכן נאסר, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובאו בה פריצים וחללוה\"\u0004 (יחזקאל ז, כב), שכיון שנכנסו לשם הגוים חיללו את הקדושה שהיתה במזבח, וכיון שהפך לחולין נאסרו אבניו אף להדיוט כשנשתמשו בהם לעבודה זרה. ומדוע גנזום?","\u0003אמרי\u0004 \u0005[אמרו]\u0006 חכמי אותו הדור: \u0003היכי נעביד\u0004 \u0005[איך נעשה]\u0006 לבטלן מאיסור עבודה זרה. כדי להכשירן למזבח? אם \u0003ניתברינהו\u0004 \u0005[נשבור אותן\u0006 את האבנים הללו] — \u0003\"אבנים שלמות\u0004 תבנה את מזבח ה' \" (דברים כז, ו) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003ננסרינהו\u0004 \u0005[ננסר אותן]\u0006 בלא לשוברן — \u0003\"לא תניף עליהם ברזל\"\u0004 (דברים כז, ה) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ואם כן אין להן תקנה אלא לגונזן.","ושואלים: \u0003ו\u0004עדיין \u0003אמאי\u0004 \u0005[מדוע]\u0006 לגונזן? \u0003ליתברינהו ולישקלינהו לנפשייהו\u0004 \u0005[שישברו אותן\u0006 כדי לבטלן, \u0005ויקחו אותן\u0006 בית חשמונאי \u0005לעצמם]\u0006 שהרי כבר נתחללו! \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר רב אושעיא: בקשו לגנוז כל כסף וזהב שבעולם משום כספא ודהבא\u0004 \u0005[כסף וזהב]\u0006 \u0003של ירושלים\u0004 שהיה במקדש, שמעורב בכל מיני כסף וזהב אחרים; \u0003והוינן בה\u0004 \u0005[והיינו מתקשים בכך]:\u0006 וכי \u0003ירושלים הויא רובא דעלמא\u0004 \u0005[היא רוב העולם]\u0006 שצריך לחשוש בכל הכסף שבעולם משום זה?","\u0003אלא אמר אביי: בקשו לגנוז דינרא הדרייאנא טוריינא שיפא\u0004 \u0005[\u0006את \u0005הדינר של אדריינוס או טריינוס המשופשף],\u0006 \u0003מפני טבעה\u0004 (מטבע) \u0003של ירושלים,\u0004 שברור היה לנו שבדינרים הללו מעורב הרבה מאד מכסף המקדש, \u0003עד שמצאו לה מקרא מן התורה שהוא מותר,\u0004 שנאמר: \u0003\"ובאו בה פריצים וחללוה\",\u0004 לומר: כיון שבאו בה — חיללוה, ושוב אין בה קדושה!","ומשיבים: אף על פי כן אינו דומה, \u0003התם\u0004 \u0005[שם]\u0006 \u0003לא אשתמשו בהו\u0004 \u0005[השתמשו בהם]\u0006 בכספים הללו \u0003לגבוה,\u0004 אלא היו רק הקדש. \u0003הכא\u0004 \u0005[כאן],\u0006 באבני המזבח, \u0003כיון דאשתמש בהו\u0004 \u0005[שהשתמשו בהם]\u0006 \u0003לגבוה\u0004 — \u0003לאו אורח ארעא לאשתמושי בהו הדיוטא\u0004 \u0005[אין\u0006 זה \u0005דרך ארץ שישתמש בהם הדיוט],\u0006 ולכן גנזום.","\u0003נכרי מבטל עבודה זרה שלו\u0004 שהוא עובד אותה, \u0003ושל חבירו\u0004 אף שהוא עצמו אינו עובד אותה, \u0003וישראל אין מבטל עבודה זרה של נכרי. המבטל עבודה זרה\u0004 — \u0003מבטל\u0004 על ידי כך גם את \u0003משמשיה,\u0004 אם \u0003ביטל\u0004 רק את \u0003משמשיה, משמשין\u0004 — \u0003מותרין, והיא\u0004 עצמה עדיין \u0003אסורה.\u0004","\u0003מתני ליה\u0004 \u0005[היה שונה לו]\u0006 \u0003רבי לר' שמעון ברבי\u0004 כנוסח משנתנו: \u0003נכרי מבטל עבודה זרה שלו ושל חבירו. אמר לו: רבי, שנית לנו בילדותך\u0004 כלומר, בהיותך צעיר יותר: \u0003נכרי מבטל עבודה זרה שלו ושל ישראל.\u0004 ותחילה תוהים: עבודה זרה של \u0003ישראל מי קא מבטלה\u0004 \u0005[האם היא מתבטלת]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"ושם בסתר\"\u0004 (דברים כז, טו) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ולמדנו מכאן שאין לה תקנה אלא גניזה! \u0003אמר ר' הילל בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' וולס: לא נצרכה\u0004 הלכה זו, אלא במקרה \u0003שיש לו\u0004 לגוי \u0003בה\u0004 בעבודה זרה זו \u0003שותפות\u0004 עם ישראל, ולכן היה מקום לומר שהוא יכול לבטלה.","ושואלים: \u0003בילדותו מאי קסבר\u0004 \u0005[מה חשב]\u0006 רבי, \u0003ובזקנותו מאי קסבר\u0004 \u0005[מה חשב],\u0006 מדוע שינה את דעתו? ומסבירים, \u0003בילדותו סבר: ישראל אדעתא דנכרי פלח\u0004 \u0005[על דעת\u0006 שותפו \u0005הגוי הוא עובד],\u0006 בגללו, ולכן \u0003כיון\u0004 שה\u0003נכרי מבטל דנפשיה\u0004 \u0005[\u0006את \u0005שלו],\u0006 של \u0003ישראל נמי מבטלה\u0004 \u0005[גם כן מתבטלת].\u0006 \u0003ובזקנותו סבר: ישראל אדעתא דנפשיה פלח\u0004 \u0005[על דעת עצמו הוא עובד],\u0006 ולכן \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מבטל נכרי דנפשיה\u0004 \u0005[\u0006את \u0005של עצמו],\u0006 של \u0003ישראל לא בטיל\u0004 \u0005[אינו בטל].\u0006","\u0003איכא דמתני לה אסיפא\u0004 \u0005[יש ששונה אותה\u0006 את השמועה הזו \u0005על סופה\u0006 של המשנה\u0005]:\u0006 \u0003ישראל אינו מבטל עבודה זרה של נכרי.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר! \u0003אמר ר' הילל בריה\u0004 \u0005[בנו]\u0006"],["של \u0003ר' וולס: לא נצרכה\u0004 הלכה זו אלא במקרה \u0003שיש לו בה שותפות\u0004 עם גוי, \u0003וקא משמע לן\u0004 \u0005[ומשמיע לנו]\u0006 שדווקא \u0003ישראל הוא\u0004 ש\u0003לא מבטל\u0004 של \u0003נכרי, אבל נכרי דנפשיה\u0004 \u0005[\u0006את החלק \u0005של עצמו]\u0006 \u0003מבטל.\u0004","\u0003איכא דמתני לה אברייתא\u0004 \u0005[יש ששונה את\u0006 הענין הזה \u0005על ברייתא],\u0006 \u0003ר' שמעון בן מנסיא אומר: עבודה זרה של ישראל אין לה בטילה עולמית.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עולמית\"?\u0004 והרי נאמר שאין לה בטילה! \u0003אמר ר' הילל בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' וולס: לא נצרכה, אלא\u0004 במקרה \u0003שיש לו לגוי בה שותפות, וקא משמע לן\u0004 \u0005[משמיע לנו],\u0006 ש\u0003ישראל אדעתא דנפשיה פלח\u0004 \u0005[על דעת עצמו עובד],\u0006 וגם אם ביטל הגוי את חלקו, חלקו של הישראל אינו בטל.","\u0003כיצד מבטלה\u0004 הגוי לעבודה זרה שלו? \u0003קטע ראש אזנה, ראש חוטמה, ראש אצבעה. פחסה\u0004 (מעך אותה), \u0003אף על פי שלא חיסרה\u0004 — \u0003ביטלה;\u0004 אבל אם \u0003רק\u0004 (ירק) \u0003בפניה, השתין בפניה, גררה\u0004 על הארץ, \u0003זרק בה את הצואה\u0004 — \u0003הרי זו אינה בטילה,\u0004 לפי שהוא רק דבר זמני, ולאחר מכן חוזר לעובדה. \u0003מכרה או משכנה\u0004 — \u0003רבי אומר: ביטל\u0004 אותה בכך, \u0003וחכמים אומרים: לא ביטל.\u0004","על האמור במשנה שאם פחסה אף על פי שלא חיסרה ביטלה, שואלים: \u0003כי\u0004 \u0005[אם]\u0006 \u0003לא חיסרה, במאי\u0004 \u0005[במה]\u0006 \u0003ביטלה? אמר ר' זירא: שפחסה בפניה\u0004 כלומר, הכה בפניה בפטיש עד שקלקל צורתה, אף שלא החסיר דבר ממנה.","שנינו במשנה: \u0003רקק בפניה, והשתין בפניה\u0004 וכו' הרי זו אינה בטילה. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שגוי הנוהג בזיון בעבודה זרה לא ביטלה על ידי כך?","\u0003אמר חזקיה,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 על עובדי אלילים: \u0003\"והיה כי ירעב והתקצף וקלל במלכו ובאלהיו ופנה למעלה\"\u0004 (ישעיה ח, כא), \u0003וכתיב בתריה\u0004 \u0005[וכתוב אחריו]:\u0006 \u0003\"ואל ארץ יביט והנה צרה וחשכה\" וגו'\u0004 (ישעיה ח, כב), והרי אנו למדים מכאן \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003קלל מלכו ואלהיו\u0004 \u0003ופנה למעלה\u0004 כלפי ה', בכל זאת — \u0003אל ארץ יביט\u0004 והנה צרה וחשכה, ששוב הוא חוזר ועובד עבודה זרה.","שנינו במשנה: \u0003מכרה או משכנה\u0004 — \u0003רבי אומר: ביטל,\u0004 וחכמים אומרים: לא ביטל. בפירוש מחלוקת זו נחלקו אמוראים, \u0003זעירי\u0004 ש\u0003אמר\u0004 בשם \u0003ר' יוחנן, ור' ירמיה בר אבא\u0004 ש\u0003אמר\u0004 בשם \u0003רב, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מחלוקת\u0004 זו היא \u0003ב\u0004מקרה שמוכרה הגוי ל\u0003צורף גוי, אבל ב\u0004מוכרה ל\u0003צורף ישראל\u0004 — \u0003דברי הכל ביטל,\u0004 שהגוי יודע שהישראל עתיד להתיכה. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: בצורף ישראל מחלוקת.\u0004","על הדעה האחרונה \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 האם הכוונה היא כי \u0003בצורף ישראל מחלוקת, אבל\u0004 המוכר ל\u0003צורף גוי דברי הכל לא ביטל, או דלמא\u0004 \u0005[שמא]\u0006 \u0003בין בזה\u0004 \u0003ובין בזה מחלוקת?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון מברייתא, ש\u0003אמר רבי: נראין דבריי\u0004 שביטל \u0003כשמכרה לחבלה, ו\u0004נראים \u0003דברי חביריי\u0004 שלא ביטל במקרה \u0003שמכרה לעובדה;\u0004 ונברר:","\u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 \u0003\"לחבלה\"\u0004 \u0003ומאי\u0004 \u0005[ומה\u0006 משמעות\u0005]\u0006 \u0003\"לעובדה\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לחבלה\u0004 — \u0003לחבלה ממש,\u0004 שהמוכר יודע שהקונה עומד לשוברה, \u0003לעובדה\u0004 — \u0003לעובדה ממש,\u0004 שהקונה עתיד לעובדה, \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם של מי שאומר]\u0006 \u0003ביטל\u0004 כשמוכרה לעובדה, \u0003ומאי טעמא למאן דאמר\u0004 \u0005[ומה הטעם של מי שאומר]\u0006 \u0003לא ביטל\u0004 אם יודע שהקונה שוברה?","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 צריך לפרש כך: לא שברור לו הדבר, אלא שמכרה \u0003לחבלה\u0004 — \u0003למי שעתיד לחבלה, ומנו\u0004 \u0005[ומי הוא]\u0006 שמסתבר שיעשה כן? \u0003צורף ישראל, לעובדה\u0004 — \u0003למי שעתיד לעובדה, ומנו\u0004 \u0005[ומי הוא]?\u0006 \u0003צורף גוי. ו\u0004ממה שאמר רבי שנראים דבריו במקרה אחד ודברי חבריו במקרה אחר \u0003שמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003בין בזה ובין בזה מחלוקת,\u0004 שלא כמי שסבור לעיל כי דווקא בצורף גוי נחלקו רבי וחכמים!","ודבר זה דוחים: \u0003לא, הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 כך יש להבין ש\u0003אמר רבי: נראין דבריי לחביריי כשמכרה לחבלה, ומנו\u0004 \u0005[ומי הוא]\u0006 שעושה כן? \u0003צורף ישראל, שאף חביריי לא נחלקו עלי אלא כשמכרה לעובדה\u0004 כלומר, לצורף גוי, \u0003אבל לחבלה\u0004 כלומר, לצורף ישראל — \u0003מודו\u0004 \u0005[מודים]\u0006 \u0003לי.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 מברייתא אחרת\u0005]:\u0006 \u0003הלוקח גרוטאות\u0004 (שברי מתכת) \u0003מן הגוים ומצא בהן עבודה זרה, אם עד שלא נתן\u0004 הקונה הישראל \u0003מעות משך\u0004 את העבודה זרה \u0003—\u0004 הרי זה \u0003יחזיר\u0004 לגוי מה שמשך, \u0003אם משנתן מעות משך,\u0004 ושוב אינו יכול להחזירה — \u0003יוליך\u0004 את העבודה הזרה \u0003לים המלח;\u0004","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]:\u0006 \u0003בצורף ישראל מחלוקת, הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]\u0006 שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 שגוי המוכר לצורף ישראל לא ביטל בכך את מה שמכר, ודינו כעבודה זרה. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]:\u0006 \u0003בצורף גוי מחלוקת, אבל בצורף ישראל דברי הכל ביטל, הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006","ומתרצים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דאדעתא דגרוטאות זבין\u0004 \u0005[שעל דעת\u0006 שהן \u0005גרוטאות מכרן],\u0006 \u0003אדעתא\u0004 \u0005[על דעת]\u0006 שיש שם \u0003עבודה זרה לא זבין\u0004 \u0005[מכר],\u0006 אלא בטעות נפלה עבודה זרה, ולא התכוון לבטלה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003לוה עליה\u0004 על עבודה זרה, שנתנה כמשכון להלואה, \u0003או שנפלה עליה מפולת, או שגנבוה ליסטין\u0004 (שודדים), \u0003או שהניחוה הבעלים והלכו למדינת הים,\u0004"],["\u0003אם עתידין\u0004 הבעלים \u0003לחזור כמלחמת יהושע\u0004 כשכבש את ארץ ישראל— \u0003אינה בטילה.\u0004","ומסבירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שיאמרו כל הדוגמאות הללו, לפי שיש בכל אחת מהן חידוש, \u0003דאי תנא\u0004 \u0005[שאם היה שונה]\u0006 רק \u0003לוה\u0004 \u0003עליה,\u0004 הייתי אומר: \u0003מדלא זבנה\u0004 \u0005[מ\u0006כיוון \u0005שלא מכרה],\u0006 אלא רק עשאה משכון, \u0003לא בטלה,\u0004 שמעולם לא הראה על כוונה לוותר עליה, \u0003אבל נפלה עליה מפולת, מדלא קא מפני לה\u0004 \u0005[מ\u0006כיוון \u0005שאינו מפנה אותה]\u0006 — \u0003אימא בטולי בטלה\u0004 \u0005[אמור\u0006 ש\u0005ביטלה]\u0006 בלבו, לכן \u0003צריכא\u0004 \u0005[צריך\u0006 הדבר להיאמר\u0005].\u0006","\u0003ואי תנא\u0004 \u0005[ואם\u0006 היה \u0005שונה]\u0006 רק \u0003נפלה עליה מפולת,\u0004 הייתי סבור שאינה בטילה \u0003משום דסבר\u0004 \u0005[שחושב\u0006 הגוי\u0005]:\u0006 \u0003הא מנחת\u0004 \u0005[הרי\u0006 העבודה הזרה \u0005מונחת\u0006 שם\u0005],\u0006 \u0003כל אימת דבעינא לה, שקילנא לה\u0004 \u0005[כל זמן שארצה אותה, אקח אותה]\u0006 ואינו מבטלה מליבו, \u0003אבל גנבוה לסטים, מדלא קא מהדר אבתרה\u0004 — \u0003בטולי בטלה\u0004 \u0005[מ\u0006כיוון \u0005שאינו מחזר אחריה\u0006 להשיבה אליו — יש מקום לומר ש\u0005בטלה\u0006 בלבו\u0005],\u0006 לכן \u0003צריכא\u0004 \u0005[צריך]\u0006 לומר זאת שאין בכך ביטול.","\u0003ואי תנא\u0004 \u0005[ואם\u0006 היה \u0005שונה]\u0006 רק \u0003גנבוה לסטין,\u0004 הייתי אומר שאינה בטילה \u0003משום דסבר\u0004 \u0005[שחושב\u0006 הגוי\u0005]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003גוי שקיל לה\u0004 \u0005[נוטל אותה]\u0006 בגזילה — הרי \u0003מפלח פלח לה\u0004 \u0005[\u0006\u0005יעבוד אותה],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003ישראל שקלה\u0004 \u0005[נטלה\u0006 בגזילה\u0005]\u0006 — \u0003איידי\u0004 \u0005[מתוך]\u0006 ש\u0003דמיה יקרין מזבין לה\u0004 \u0005[\u0006הריהו \u0005מוכר אותה]\u0006 \u0003לגוי ופלח לה\u0004 \u0005[ועובד אותה]\u0006 אותו גוי, ולכן אינו מבטלה בליבו, \u0003אבל הניחוה הבעלים והלכו למדינת הים, מדלא שקלו בהדייהו\u0004 \u0005[מ\u0006כיוון \u0005שלא נטלו אותה\u0006 עמהם\u0005]\u0006 — \u0003בטולי בטלוה\u0004 \u0005[\u0006אמור ש\u0005ביטלוה],\u0006 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמר גם במקרה זה שאין בכך ביטול.","שנינו בברייתא: \u0003אם עתידין\u0004 הבעלים \u0003לחזור כמלחמת יהושע\u0004 — \u0003אינה בטילה.\u0004 ותוהים: \u0003מידי\u0004 \u0005[כלום]\u0006 ב\u0003מלחמת יהושע מיהדר הדור\u0004 \u0005[חזרו]\u0006 הגוים למקומם? הרי הובסו במלחמה ונהרגו, ולא חזרו! ומשיבים, \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אם עתידין לחזור\u0004 — \u0003הרי\u0004 דינה \u0003הוא כמלחמת יהושע ואין לה בטילה.\u0004","ושואלים: \u0003ולמה לי למיתלייה\u0004 \u0005[לתלות אותה]\u0006 לקשר את הדבר \u0003במלחמת יהושע?\u0004 ומשיבים: \u0003מלתא אגב אורחא קא משמע לן\u0004 \u0005[דבר בדרך אגב משמיע לנו],\u0006 שיש ללמוד הלכות עבודה זרה לפרטיה ממלחמת יהושע, \u0003כי הא\u0004 \u0005[כמו\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר רב יהודה אמר רב: ישראל שזקף לבינה להשתחות לה,\u0004 ולא השתחווה, \u0003ובא גוי והשתחוה לה\u0004 — \u0003אסרה,\u0004 אף שאינה שייכת לו.","ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 ש\u0003אסרה? אמר ר' אלעזר: כתחילה של\u0004 הכניסה ל\u0003ארץ ישראל, דאמר רחמנא\u0004 \u0005[שאמרה התורה]\u0006 \u0003\"ואשריהם תשרפון באש\"\u0004 (דברים יב, ג), ויש לתמוה: \u0003מכדי\u0004 \u0005[הרי]\u0006 ארץ ישראל \u0003ירושה היא להם\u0004 לישראל עוד \u0003מאבותיהם\u0004 (אברהם יצחק ויעקב) \u0003ואין אדם אוסר דבר שאינו שלו,\u0004 ואם כן כיצד יכולים הגוים לאסור את האשירות, כאשר בעצם אין הארץ שלהם!","\u0003ואי\u0004 \u0005[ואם]\u0006 תאמר שחוששים \u0003משום הנך דמעיקרא\u0004 \u0005[\u0006אלה \u0005שמתחילה]\u0006 שעבדו הגוים לפני אברהם — הרי זו עבודה זרה של גוי, \u0003בביטולא בעלמא סגי להו\u0004 \u0005[ובביטול בלבד די להם]\u0006 שיבטלום הגוים בעל כרחם, ולא יצטרכו לשורפם!","\u0003אלא\u0004 יש להבין כי \u0003מדפלחו\u0004 \u0005[מ\u0006כיוון \u0005שעבדו]\u0006 \u0003ישראל לעגל, גלו אדעתייהו\u0004 \u0003דניחא להו\u0004 \u0005[גילו דעתם שנוח להם]\u0006 שהם רוצים \u0003בעבודה זרה, וכי אתו\u0004 \u0005[וכאשר באו]\u0006 \u0003גוים\u0004 ועשו אלילים, \u0003שליחותא דידהו עבדי\u0004 \u0005[שליחות שלהם,\u0006 של ישראל, \u0005עשו],\u0006 ולכן האשירות נאסרות כדין עבודה זרה של ישראל, שאין לה ביטול. \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003ישראל שזקף לבינה\u0004 כדי להשתחוות לה, \u0003גליא דעתיה דניחא ליה\u0004 \u0005[מגלה דעתו שנוח לו]\u0006 \u0003בעבודה זרה, וכי אתא\u0004 \u0005[וכאשר בא]\u0006 \u0003גוי ופלח לה\u0004 \u0005[ועובד אתה],\u0006 \u0003שליחותא דידיה קעביד\u0004 \u0005[שליחות שלו,\u0006 של ישראל, \u0005הוא עושה].\u0006","על עיקר הסברה מקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003בעגל\u0004 בלבד \u0003הוא דניחא להו\u0004 \u0005[שנוח\u0006 היה \u0005להם],\u0006 \u0003במידי אחרינא\u0004 \u0005[בדבר אחר]\u0006 בעבודה זרה אחרת \u0003לא!\u0004 ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בחטא העגל \u0003\"אלה אלהיך ישראל\"\u0004 (שמות לב, ד), בלשון רבים, הרי זה \u0003מלמד\u0004 שלא לעגל בלבד עבדו, אלא \u0003שאיוו לאלוהות הרבה\u0004 וקיבלו עליהם כל מיני עבודה זרה.","ושואלים: \u0003אימא\u0004 \u0005[אמר]\u0006 לפי זה כי \u0003כל דבהדי\u0004 \u0005[\u0006שהיה \u0005יחד]\u0006 עם ה\u0003עגל\u0004 באותו זמן שעבדוהו \u0003ניתסרו?\u0004 \u0005[ייאסר],\u0006 שבו עשו הכנענים את שליחותם של ישראל, ואילו כל ענייני עבודה זרה שנעשו \u0003מכאן ואילך\u0004 כאשר חזרו ישראל בתשובה ושוב אינם עובדים עבודה זרה] \u0003נישתרי\u0004 \u0005[יהיו מותרים]!\u0006 ומתרצים: \u0003מאן מוכח\u0004 \u0005[מי מוכיח]\u0006 כלומר, מי יכול להבחין אלו אשירות הן מאותו זמן ואלו נעשו לאחר מכן, ולכן נאסר הכל.","\u0003עבודה זרה שהניחוה עובדיה,\u0004 אם הניחוה \u0003בשעת שלום\u0004 — הרי היא \u0003מותרת,\u0004 שמוכח שהפקירוה ואינם רוצים בה עוד. הניחוה \u0003בשעת מלחמה\u0004 — \u0003אסורה,\u0004 שלא מרצונם עזבוה. \u0003בימוסיאות\u0004 (בסיסי אבן) שמניחים עליהם עבודה זרה לכבודם \u0003של מלכים\u0004 — \u0003הרי אלו מותרות, מפני שמעמידין אותה בשעה שהמלכים עוברים.\u0004","\u0003אמר ר' ירמיה בר אבא אמר רב: בית נמרוד\u0004 (שרידי מגדל בבל) \u0003הרי היא כעבודה זרה שהניחוה עובדיה בשעת שלום, ומותר.\u0004 וטעם הדבר, כי \u0003אף על גב דכי בדרינהו\u0004 \u0003רחמנא\u0004 \u0005[אף על פי שכאשר פיזרם הקב\"ה]\u0006 \u0003כשעת מלחמה דמי\u0004 \u0005[נחשב]\u0006 הדבר, שהרי יצאו משם על כרחם \u0003אי בעיא למיהדר הדור\u0004 \u0005[אם היו רוצים לחזור\u0006 היו \u0005חוזרים],\u0006 \u0003מ\u0004כיוון ש\u0003לא הדור\u0004 \u0005[חזרו]\u0006 \u0003בטולי בטלה\u0004 \u0005[ביטלוה\u0006 בליבם\u0005].\u0006","שנינו במשנה: \u0003בימוסיאות\u0004 \u0003של מלכים\u0004 — \u0003הרי אלו מותרות\u0004 מפני שמעמידין אותה בשעה שהמלכים עוברים. ותוהים על הנימוק: \u0003וכי מפני שמעמידין אותה בשעה שהמלכים עוברין מותרין?\u0004 מה הוא ההיתר שיש בזה?","\u0003אמר רבה בר בר חנה אמר ר' יוחנן, הכי קאמר\u0004 \u0005[כך הוא אמר],\u0006 כך משמעות הדברים: \u0003מפני שמעמידין אותן בשעה שהמלכים עוברין, ומלכים מניחין דרך זו\u0004 שהעמידו בה את הבימוס \u0003והולכין בדרך אחרת,\u0004 אין הם נחשבים כמשמשי עבודה זרה.","ובענין בימוס מסופר, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003עולא,\u0004 מארץ ישראל \u0003יתיב אבימסא פגימא\u0004 \u0005[ישב על בימוס פגום].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה לעולא, והא\u0004 \u0005[והרי]\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003בימוס\u0004 \u0003שנפגם\u0004 — \u0003אסור! ואפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003אין\u0004 הגוים \u0003עובדים לשברים\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 ב\u0003עבודה זרה, דזילא ביה מלתא למפלח\u0004 \u0005[\u0006מפני \u0005שמזולזל בעיניהם לעבוד]\u0006 \u0003לשברים, אבל האי\u0004 \u0005[זה,\u0006 הבימוס\u0005]\u0006 \u0003לא איכפת ליה\u0004 \u0005[לו]\u0006 שהוא פגום, שהוא עדין ראוי להעמיד עליו פסל!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאן יהיב לן מעפרא דרב ושמואל ומלאינן עיינין\u0004 \u0005[מי יתן לנו מעפרם של רב ושמואל ונמלא עינינו]\u0006 שהיו אנשים גדולים וקדושים. אבל לענין הלכה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ר' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 להיפך: \u0003בימוס שנפגם\u0004 — \u0003מותר. ואפילו למאן דאמר\u0004 \u0005[\u0006לדעת \u0005מי שאומר]\u0006 \u0003עובדין לשברים, הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 ב\u0003עבודה זרה\u0004 עצמה, \u0003דכיון דפלחה\u0004 \u0003זילא ביה מילתא לבטולה\u0004 \u0005[שכיון שעבדה מזולזל\u0006 בעיניו לחזור \u0005ולבטלה],\u0006 \u0003אבל הני שקלי להאי\u0004 \u0003ומייתו בימוס אחרינא\u0004 \u0005[אלה לוקחים\u0006 בימוס \u0005זה\u0006 ומשליכים אותו, \u0005ומביאים בימוס אחר]\u0006 שאינו פגום.","ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתם]\u0006 של \u0003ר' יוחנן וריש לקיש: בימוס שנפגם\u0004 — \u0003מותר, מזבח\u0004 לעבודה זרה \u0003שנפגם\u0004 — \u0003אסור עד שינתץ רובו.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא]\u0006 \u0003בימוס, היכי דמי\u0004 \u0005[כיצד הוא]\u0006 \u0003מזבח? אמר ר' יעקב בר אידי אמר ר' יוחנן: בימוס\u0004 — עשוי \u0003אבן אחת, מזבח\u0004 — בנוי \u0003אבנים הרבה.\u0004"],["\u0003אמר חזקיה: מאי קרא\u0004 \u0005[מה המקרא]\u0006 שממנו נלמדת הלכה זו? שנאמר \u0003\"בשומו כל אבני מזבח כאבני גיר מנפצות לא יקמו אשרים וחמנים\"\u0004 (ישעיהו כז, ט), \u0003אי איכא\u0004 \u0005[אם מתקיים]\u0006 \u0003כאבני גיר מנופצות\u0004 — \u0003לא יקומון אשרים וחמנים\u0004 והם בטלים, \u0003אי לאו\u0004 \u0005[אם לא]\u0006 — \u0003יקומו.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003נעבד\u0004 כגון בעל חיים שעובד אותו כעבודה זרה, אם היה זה בעל חיים \u0003שלו\u0004 (של העובד) — הרי זה \u0003אסור, ושל חבירו מותר. ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ששנינו: \u0003איזהו נעבד\u0004 שנאסר להקריבו במקדש? \u0003כל שעובדים אותו בין בשוגג ובין במזיד, בין באונס ובין ברצון;\u0004 ונברר: \u0003האי אונס היכי דמי\u0004 \u0005[אונס זה\u0006 שנזכר \u0005כיצד הוא]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003כגון\u0004 ש\u0003אנס\u0004 (לקח בכח, שלא ברשות) \u0003בהמת חבירו והשתחוה לה?\u0004 הרי שיכול לאסור גם את בהמת חבירו!","\u0003אמר רמי בר חמא: לא, כגון שאנסוהו\u0004 (הכריחוהו) \u0003גוים והשתחוה לבהמתו דידיה\u0004 \u0005[שלו].\u0006 \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: אונס רחמנא פטריה\u0004 \u0005[פטרה אותו התורה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לגבי נערה אנוסה: \u0003\"ולנערה לא תעשה דבר\"\u0004 (דברים כב, כו)!","\u0003אלא אמר רבא: הכל,\u0004 כל אופן שעובדים בו עבודה זרה, \u0003היו בכלל\u0004 איסור \u0003\"לא תעבדם\"\u0004 (שמות כ, ה) ואף באונס, \u0003וכשפרט לך הכתוב: \"וחי בהם\"\u0004 (ויקרא יח, ה) \u0003ולא שימות בהם\u0004 — \u0003יצא אונס,\u0004 שאין אדם נידון בו כעובד עבודה זרה, ואינו חייב למסור עצמו למיתה,","\u0003והדר כתב רחמנא\u0004 \u0005[וחזרה וכתבה התורה]:\u0006 \u0003\"ולא תחללו את שם קדשי\"\u0004 (ויקרא כב, לב) ללמד ש\u0003אפילו באונס\u0004 חל איסור עבודה זרה, שהרי גם בכך יש חילול השם; \u0003הא כיצד\u0004 מתיישבת הסתירה? \u0003הא\u0004 \u0005[זה]\u0006 שאינו חייב למסור עצמו — \u0003בצנעא, והא\u0004 \u0005[וזה]\u0006 שחל איסור עבודה זרה, וחייב למסור עצמו למיתה — \u0003בפרהסיא,\u0004 ולפיכך אם אנסוהו לעבוד בהמה בפרהסיא — הבהמה נאסרת.","\u0003אמרו ליה\u0004 \u0003רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא, תניא דמסייעא\u0004 \u0005[שנויה\u0006 ברייתא \u0005המסייעת]\u0006 \u0003לך: בימוסיאות\u0004 מצבות שעובדים עליהן עבודה זרה \u0003של גוים בשעת השמד\u0004 כשגזרו על ישראל לעבוד עבודה זרה, ושעת השמד כפרהסיא היא, שחייב אדם למסור עצמו למיתה, \u0003אף על פי שהשמד בטל\u0004 — \u0003אותן בימוסיאות לא בטלו\u0004 למרות שהיה זה באונס.","\u0003אמר להו\u0004 \u0005[להם]\u0006 רבא: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[זו]\u0006 \u0003לא תסייען\u0004 \u0005[תסייעוני],\u0006 מכאן אין הוכחה למקרה של אונס, שכן שם \u0003אימר\u0004 \u0005[אמור]:\u0006 שמא \u0003ישראל משומד הוה\u0004 \u0005[היה\u0006 שם\u0005]\u0006 \u0003ופלח לה\u0004 \u0005[ועבד אותה]\u0006 \u0003ברצון. רב אשי אמר: לא תימא אימר\u0004 \u0005[אל תאמר \"אמור\"]\u0006 שמספק אתה חושש לכך, \u0003אלא ודאי ישראל משומד הוה\u0004 \u0005[היה]\u0006 \u0003ופלח לה\u0004 \u0005[ועבד אותה]\u0006 \u0003ברצון,\u0004 ומשום כך נאסרו הבימוסאות.","\u0003חזקיה אמר,\u0004 את הסתירה לגבי בהמה שאינה שלו אפשר ליישב בדרך אחרת: בברייתא האוסרת מדובר \u0003כגון שניסך לעבודה זרה יין על קרניה\u0004 של בהמה שאינה שלו, שעשה מעשה בגופה של הבהמה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אדא בר אהבה: האי\u0004 \u0005[\u0006וכגון \u0005זה]\u0006 \u0003נעבד הוא?\u0004 הרי לא עבד את הבהמה, \u0003האי\u0004 \u0005[\u0006כגון \u0005זה]\u0006 \u0003בימוס בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 הרי רק השתמש בה כמזבח לצורך עבודה זרה, \u0003ושרייה\u0004 \u0005[ומותר]!\u0006","\u0003אלא אמר רב אדא בר אהבה:\u0004 באותה ברייתא מדובר \u0003כגון שניסך לה\u0004 עצמה, כדי לעובדה, \u0003יין בין קרניה.\u0004 והטעם שיכול לאסור בהמה שאינה שלו, הוא מפני \u0003דעבד\u0004 \u0005[שעשה]\u0006 \u0003בה מעשה, וכי הא דאתא\u0004 \u0005[וכמו\u0006 הלכה \u0005זו שכאשר בא]\u0006 \u0003עולא\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן: אף על פי שאמרו המשתחוה לבהמת חבירו לא אסרה,\u0004 אם \u0003עשה בה מעשה\u0004 — \u0003אסרה.\u0004","כשאמרו דברים אלה בשם עולא \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן\u0004 לחכמים: \u0003פוקו\u0004 \u0005[צאו]\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]\u0006 \u0003לעולא: כבר תרגמה רב הונא לשמעתיך\u0004 \u0005[להלכתך]\u0006 \u0003בבבל,\u0004 שקבע הלכה זו עצמה בלשון אחרת, ש\u0003אמר רב הונא: היתה בהמת חבירו רבוצה\u0004 \u0003בפני עבודה זרה, כיון ששחט בה סימן אחד\u0004 (קנה או ושט) — \u0003אסרה,\u0004 והטעם — משום שעשה בה מעשה, אף שאינה שלו.","ומבררים הלכה זו: \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 ש\u0003אסרה? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003מכהנים,\u0004 שכהנים שעבדו לעבודה זרה נפסלו מלעבוד במקדש, שגם אם לא עשו זאת מרצונם בכל זאת גופם נאסר לגבוה — \u0003ודלמא שאני\u0004 \u0005[ושמא שונים]\u0006 \u0003כהנים,\u0004 ש\u0003בני דעה נינהו\u0004 \u0005[הם],\u0006 ויש מקום לקונסם!","\u0003ואלא\u0004 למד \u0003מאבני מזבח,\u0004 שאף שהן של הקדש, כיון שבאו היוונים וטימאום נאסרו, אף שאינן שלהם — \u0003ודלמא\u0004 \u0005[ושמא]\u0006 יש להסביר דבר זה \u0003כ\u0004מו שאמר \u0003רב פפא,\u0004 שלמדו מן הכתובים כי הגוים שנכנסו למקדש הוציאוהו מרשות הקדש וכך הפך לשלהם (ראה לעיל עבודה זרה נב,ב), אבל אין מכאן הוכחה שאדם אוסר דבר שאינו שלו!"],["\u0003ואלא מכלים\u0004 של המקדש שעבדו בהם עבודה זרה ונאסרו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת כל הכלים אשר הזניח המלך אחז במלכותו במעלו הכנו והקדשנו\"\u0004 (דברי הימים ב כט, יט), \u0003ואמר מר\u0004 [\u0005החכם,\u0006 רבי\u0005]\u0006 בפירוש הכתוב: \u0003\"הכנו\"\u0004 — \u0003שגנזנום,\u0004 לפי שנאסרו בעבודה זרה שעבדו בהם, \u0003\"והקדשנו\"\u0004 — \u0003שהקדשנו אחרים תחתיהן.\u0004 ויש לשאול: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אין אדם אוסר דבר שאינו שלו,\u0004 וכלי המקדש שייכים לגבוה ולא לבני אדם!","\u0003אלא כיון דעבד בהו\u0004 \u0005[שעשה בהם]\u0006 אחז \u0003מעשה\u0004 של עבודה זרה \u0003איתסרו להו\u0004 \u0005[נאסרו להם],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 בשוחט בהמת חבירו לעבודה זרה — \u0003כיון שעשה בה מעשה, אסרה.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן: אף על פי שאמרו המשתחוה לקרקע עולם לא אסרה,\u0004 אם \u0003חפר בה בורות שיחין ומערות\u0004 לעבודה זרה — \u0003אסרה. כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב שמואל בר יהודה אמר ר' יוחנן: אף על פי שאמרו המשתחוה לבעלי חיים לא אסרן,\u0004 אם \u0003עשאן חליפין לעבודה זרה,\u0004 שהחליף עבודה זרה שלו בבעלי חיים — \u0003אסרן.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר: פליגו\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בהלכה זו \u0003ר' ישמעאל בר ר' יוסי ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: חליפין\u0004 של עבודה זרה \u0003אסורין,\u0004 אבל \u0003חליפי חליפין\u0004 מה שהחליף בחליפי עבודה זרה (או בדמים שקיבל עבורה) \u0003מותרין; וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אפילו חליפי חליפין נמי\u0004 \u0005[גם כן]\u0006 \u0003אסורין.\u0004","ומבררים: \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם של מי שאומר]:\u0006 \u0003חליפי חליפין אסורין? אמר קרא\u0004 \u0005[המקרא]\u0006 בענין עבודה זרה: \u0003\"\u0004לא תביא תועבה אל ביתך \u0003והיית חרם כמהו\"\u0004 (דברים ז, כו), ומכאן למדים: \u0003כל שאתה מהיה\u0004 (יוצר, מגדל) \u0003ממנו\u0004 — \u0003הרי הוא כמוהו.\u0004 ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 מהיכן הוא למד שמותרים הם? \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \"כי חרם \u0003הוא\"\u0004 (דברים ז, כו), והרי זו הדגשה, למעט: דווקא \u0003הוא\u0004 נאסר — \u0003ולא חליפי חליפין.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 מה למד הוא ממיעוט זה? ומשיבים: \u0003ההוא מיבעי ליה למעוטי\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו למעט]\u0006 \u0003ערלה וכלאי הכרם,\u0004 שאין חליפיהם נאסרים בהנאה, וכרכושו נחשבים, עד \u0003שאם מכרן וקידש\u0004 אשה \u0003בדמיהן\u0004 — \u0003מקודשת.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 מנין למד הוא הלכה זו? ומשיבים: לדעתו \u0003ערלה וכלאי הכרם לא צריכי מיעוטא\u0004 \u0005[אינם צריכים מיעוט],\u0006 \u0003דהויא להו\u0004 \u0005[שהרי הם]\u0006 \u0003עבודה זרה ושביעית שני כתובין הבאין כאחד,\u0004 שבשניהם אמרה התורה שחל האיסור גם על החליפין, \u0003וכל שני כתובין הבאין כאחד אין מלמדין\u0004 על דינים אחרים. ומהיכן למדנו את איסור החליפין שלהם?","\u0003עבודה זרה\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 מ\"והיית חרם כמוהו\", \u0003שביעית\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי יובל הוא קדש תהיה לכם\"\u0004 (ויקרא כה, יב), ללמד: \u0003מה קדש תופס את דמיו\u0004 שאם קונים דבר מן ההקדש הדמים נתפסים בקדושה \u0003ואסור, אף שביעית תופסת את דמיה ואסורה;\u0004 אלא שעל כך יש לשאול:","\u0003אי\u0004 \u0005[אם\u0006 כן\u0005]\u0006 נאמר: \u0003מה קדש תופס את דמיו ו\u0004הוא עצמו \u0003יוצא לחולין, אף שביעית תופסת את דמיה\u0004 שתמורתה נתפסת בקדושת שביעית \u0003ו\u0004היא \u0003יוצאה לחולין! תלמוד לומר: \"תהיה\"\u0004 (ויקרא כה, יב) לומר: \u0003בהוייתה\u0004 (כמות שהיא) \u0003תהא,\u0004 ולא תשתנה,","\u0003הא כיצד?\u0004 \u0003לקח\u0004 (קנה) \u0003בפירות שביעית בשר\u0004 — \u0003אלו ואלו מתבערין בשביעית\u0004 שבשר זה חלה עליו קדושת אותם פירות שביעית, וכשמגיע זמן ביעור הפירות אף הבשר צריך ביעור, \u0003לקח בבשר דגים\u0004 — \u0003יצא בשר נכנסו דגים,\u0004 לקח \u0003בדגים יין\u0004 — \u0003יצאו דגים נכנס יין,\u0004 לקח \u0003ביין שמן\u0004 — \u0003יצא יין ונכנס שמן, הא כיצד? אחרון אחרון\u0004 שקנה מדמי שביעית או חלופיה \u0003נתפס בשביעית, ופרי עצמו\u0004 של שביעית \u0003אסור.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 הסבור שחליפי חליפין של עבודה זרה אסורים, מה הוא משיב על כך? \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003שני כתובין הבאין כאחד מלמדין,\u0004 והיה מקום, איפוא, ללמוד (מעבודה זרה ושביעית) שגם ערלה וכלאי הכרם יאסרו את חליפיהם, \u0003ואיצטריך\u0004 \u0005[ונצרך]\u0006 הבטוי \u0003\"הוא\" למעוטינהו\u0004 \u0005ולמעט אותם].\u0006","\u0003שאלו את הזקנים\u0004 (חכמי ישראל) כאשר היו \u0003ברומי: אם אין רצונו\u0004 של הקדוש ברוך הוא \u0003בעבודה זרה, למה אינו מבטלה\u0004 מן העולם? \u0003אמרו להן\u0004 הזקנים: \u0003אילו לדבר שאין צורך לעולם בו היו עובדין\u0004 — \u0003היה מבטלו,\u0004 ואולם \u0003הרי הן עובדין לחמה וללבנה ולכוכבים ולמזלות,\u0004 וכי \u0003יאבד עולמו מפני השוטים?\u0004","\u0003אמרו להן: אם כן, יאבד דבר\u0004 שעובדים אותו \u0003שאין צורך לעולם בו, ויניח\u0004 ולא יאבד \u0003דבר שצורך העולם בו! אמרו להן:\u0004 אם כך היה קורה \u0003אף אנו מחזיקין ידי עובדיהן של אלו\u0004 חמה ולבנה וכיוצא בהם, \u0003שאומרים: תדעו שהן אלוהות, שהרי הן לא בטלו.\u0004","ובדומה למה ששנינו במשנתנו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003שאלו פלוסופין את הזקנים ברומי: אם אלהיכם אין רצונו בעבודה זרה, מפני מה אינו מבטלה? אמרו להם: אילו לדבר שאין העולם צורך לו היו עובדין הרי הוא מבטלה.\u0004 ואולם \u0003הרי הן עובדין לחמה וללבנה ולכוכבים ולמזלות, יאבד עולם מפני השוטים? אלא עולם כמנהגו נוהג, ושוטים שקלקלו עתידין ליתן את הדין.\u0004","\u0003דבר אחר\u0004 להסביר אותו רעיון בדוגמה אחרת: \u0003הרי שגזל\u0004 אדם \u0003סאה של חטים והלך וזרעה בקרקע\u0004 — \u0003דין הוא שלא תצמח,\u0004 לפי שעשה בה עבירה, \u0003אלא עולם כמנהגו נוהג והולך, ושוטים שקלקלו\u0004 וחטאו הם \u0003עתידין ליתן את הדין.\u0004","\u0003דבר אחר: הרי שבא על אשת חבירו\u0004 — \u0003דין הוא שלא תתעבר, אלא עולם כמנהגו נוהג והולך, ושוטים שקלקלו עתידין ליתן את הדין.\u0004","ומעירים: \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ריש לקיש, אמר הקדוש ברוך הוא: לא דיין\u0004 (די להם) \u0003לרשעים שעושין סלע\u0004 (מטבע) \u0003שלי פומבי\u0004 הפקר, שמשתמשים בה שלא ברשותי וכנגד רצוני, שהם נואפים ומעברים נשים באיסור, \u0003אלא ש\u0004הם גם \u0003מטריחין אותי ומחתימין אותי\u0004 עליה \u0003בעל כרחי,\u0004 שהרי הקדוש ברוך הוא נותן צורה וחיים לוולד אף שנוצר באיסור.","ועוד בענין זה \u0003שאל פלוספוס אחד את רבן גמליאל, כתוב בתורתכם\u0004 באיסור עבודה זרה: \u0003\"כי ה' אלהיך אש אכלה הוא אל קנא\"\u0004 (דברים ד, כד), \u0003מפני מה מתקנא בעובדיה\u0004 ומענישם, \u0003ואין מתקנא בה\u0004 ומשמיד עבודה זרה עצמה?","\u0003אמר לו: אמשול לך משל, למה הדבר דומה? למלך בשר ודם שהיה לו בן אחד, ואותו הבן היה מגדל לו את הכלב והעלה\u0004 (וקרא, כינה) \u0003לו\u0004 לכלב \u0003שם על שם אביו, וכשהוא נשבע\u0004 — \u0003אומר: \"בחיי כלב אבא\", כששמע המלך, על מי הוא כועס, על הבן הוא כועס או על הכלב הוא כועס? הוי אומר: על הבן הוא כועס.\u0004 כך כשעובדי עבודה זרה קוראים לה אלוה — עליהם הוא כועס, ולא עליה.","\u0003אמר לו\u0004 אותו פלוספוס: \u0003כלב אתה קורא אותה\u0004 לעבודה זרה? \u0003והלא יש בה ממש! אמר לו: ומה ראית\u0004 להוכיח שיש בה ממש? \u0003אמר לו: פעם אחת נפלה דליקה בעירנו, ונשרפה כל העיר כולה, ואותו בית עבודה זרה לא נשרף!\u0004","\u0003אמר לו\u0004 רבן גמליאל: \u0003אמשול לך משל, למה הדבר דומה? למלך בשר ודם שסרחה\u0004 (חטאה) \u0003עליו מדינה, כשהוא עושה מלחמה, עם החיים הוא עושה או עם המתים הוא עושה? הוי אומר: עם החיים הוא עושה.\u0004","\u0003אמר לו: כלב אתה קורא אותה, מת אתה קורא אותה, אם כן יאבדנה מן העולם! אמר לו: אילו לדבר שאין העולם צריך לו היו עובדין\u0004 — \u0003הרי הוא\u0004 היה \u0003מבטלה,\u0004 אבל \u0003הרי הן עובדין לחמה וללבנה, לכוכבים\u0004 \u0003ולמזלות, לאפיקים ולגאיות, יאבד עולמו מפני שוטים? וכן הוא אומר:\u0004"],["\u0003\"אסף אסף כל מעל פני האדמה נאם ה', אסף אדם ובהמה אסף עוף השמים ודגי הים והמכשלות את הרשעים\" וגו'\u0004 (צפניה א, ב—ג), \u0003וכי מפני שהרשעים נכשלים בהן יאבדם מן העולם? ו\u0004כיוצא בזה: \u0003הלא לאדם הן עובדין, \"והכרתי את האדם מעל פני האדמה\" וגו'\u0004 (צפניה א, ג—ד)?","\u0003שאל אגריפס שר צבא\u0004 שהיה גוי, ושר צבא של מלך ישראל \u0003את רבן גמליאל, כתיב בתורתכם: \"כי ה' אלהיך אש אכלה הוא אל קנא\"\u0004 (דברים ד, כד), \u0003כלום מתקנא אלא חכם בחכם, וגבור בגבור ועשיר בעשיר,\u0004 ומדוע יתקנא הקדוש ברוך הוא בעבודה זרה שאין בה ממש?","\u0003אמר לו: אמשול לך משל, למה הדבר דומה? לאדם שנשא אשה\u0004 נוספת \u0003על אשתו,\u0004 אם היתה האשה השניה \u0003חשובה ממנה\u0004 — \u0003אין מתקנאה בה,\u0004 כלומר, אינה כועסת על בעלה בגללה, אבל אם היתה \u0003פחותה ממנה\u0004 — \u0003מתקנאה בה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003זונין לר' עקיבא: לבי ולבך ידע\u0004 \u0005[יודע]\u0006 ש\u0003עבודה זרה לית\u0004 \u0005[אין]\u0006 \u0003בה מששא\u0004 \u0005[ממש],\u0006 \u0003והא קחזינן גברי דאזלי כי מתברי ואתו כי מצמדי\u0004 \u0005[ו\u0006אולם \u0005הרי אנו רואים אנשים שהולכים\u0006 לעבודה זרה \u0005כשהם שבורים ובאים כשהם שלמים],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006","\u0003אמר לו\u0004 ר' עקיבא: \u0003אמשול לך משל, למה הדבר דומה? לאדם נאמן שהיה בעיר, וכל בני עירו היו מפקידין אצלו\u0004 חפצים וכסף שלהם \u0003שלא בעדים\u0004 מתוך שסומכים עליו, \u0003ובא אדם אחד\u0004 שלא סמך עליו \u0003והפקיד לו\u0004 פקדונותיו דווקא \u0003בעדים. פעם אחד שכח והפקיד אצלו שלא בעדים, אמרה לו אשתו\u0004 של אותו שומר נאמן: \u0003בוא ונכפרנו,\u0004 שהרי הפעם אין בידו עדים! \u0003אמר לה: וכי מפני ששוטה זה עשה שלא כהוגן\u0004 ולא הפקיד בעדים כדרכו, \u0003אנו נאבד את אמונתינו\u0004 וניעשה שקרנים?","\u0003אף כך יסורין, בשעה שמשגרין אותן על האדם, משביעין אותן: שלא תלכו\u0004 אליו \u0003אלא ביום פלוני, ולא תצאו\u0004 ממנו \u0003אלא ביום פלוני ובשעה פלונית, ועל ידי\u0004 רופא \u0003פלוני ועל ידי סם פלוני. כיון שהגיע זמנן\u0004 של היסורים \u0003לצאת\u0004 מאותו אדם, \u0003הלך זה\u0004 \u0003לבית עבודה זרה, אמרו יסורין: דין הוא שלא נצא\u0004 ממנו, \u0003וחוזרין ואומרים: וכי מפני ששוטה זה עושה שלא כהוגן אנו נאבד שבועתנו?\u0004","ומעירים: \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"וחלים רעים ונאמנים\"?\u0004 (דברים כח, נט), החליים הם \u0003רעים בשליחותן\u0004 שתפקידם לעשות רע, \u0003ונאמנים בשבועתן\u0004 לבוא ולצאת בזמן הקבוע להם.","וכיוצא בזה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר רב יצחק לרב יהודה: האיכא\u0004 \u0005[הרי יש]\u0006 \u0003בית עבודה זרה באתרין\u0004 \u0005[במקומנו],\u0006 \u0003דכי מצטריך עלמא למטרא\u0004 \u0005[שכאשר צריך העולם לגשם],\u0006 \u0003מתחזי להו בחלמא ואמר להו\u0004 \u0005[נראה להם\u0006 אליל זה \u0005בחלום ואומר להם]:\u0006 \u0003שחטו לי גברא ואייתי מטרא\u0004 \u0005[אדם ואביא גשם],\u0006 \u0003שחטו לה גברא ואתי מטרא\u0004 \u0005[\u0006ו\u0005שוחטים לו איש ובא גשם]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003השתא, אי הוי שכיבנא, לא אמרי לכו הא מלתא\u0004 \u0005[עכשיו, אם הייתי מת, לא הייתי אומר לכם דבר זה],\u0006 שיפה עשיתם ששאלתם, כי על ידי כך נזכרתי ש\u0003אמר רב, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \"וראית את השמש ואת הירח... \u0003אשר חלק ה' אלהיך אתם לכל העמים\"\u0004 (דברים ד, יט)? \u0003מלמד שהחליקן\u0004 הקדוש ברוך הוא \u0003בדברים\u0004 הניח להם לטעות בדבר, \u0003כדי לטורדן מן העולם\u0004 על שבחרו לעבוד עבודה זרה.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 העניין ש\u0003אמר\u0004 \u0003ריש לקיש\u0004 בכלל ההנהגה של מעלה, \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אם ללצים הוא יליץ ולענוים יתן חן\"\u0004 (משלי ג, לד)? אם אדם \u0003בא לטמא\u0004 — \u0003פותחין לו\u0004 שנותנים לו משמים אפשרות לכך ואין מונעים ממנו, אם \u0003בא לטהר\u0004 — \u0003מסייעין אותו.\u0004","\u0003לוקחין גת בעוטה\u0004 (שדרכה הגוי ברגליו עד שיצא המיץ מן הענבים) \u0003מן הנכרי, אף על פי שהוא\u0004 הנכרי \u0003נוטל בידו\u0004 ענבים מן הגת \u0003ונותן לתפוח\u0004 (ערימת ענבים לדריכה שבתוכה), שאין חוששים למגעו. \u0003ואינו עושה יין נסך עד שירד\u0004 המיץ \u0003לבור\u0004 שאז נדון כיין. ולאחר ש\u0003ירד לבור\u0004 — \u0003מה שבבור אסור\u0004 שהוא יין נסך, \u0003והשאר\u0004 שלא ירד לבור עדיין \u0003מותר.\u0004","\u0003דורכין עם הנכרי בגת,\u0004"],["\u0003אבל לא בוצרין עמו\u0004 לפי שבכך מטמאים את הענבים, שהגת טמאה, ואסור לגרום טומאה לפירות ארץ ישראל. \u0003ישראל שהוא עושה\u0004 יינו \u0003בטומאה\u0004 — אף \u0003לא דורכין ולא בוצרין עמו,\u0004 שאין לסייע לעוברי עבירה, \u0003אבל\u0004 לאחר שגמר כבר לעשות את יינו, \u0003מוליכין עמו חביות לגת ומביאין עמו מן הגת,\u0004 שהיין כבר נטמא, ואין זה מסייע לו בטומאה.","וכיוצא בדבר, \u0003נחתום\u0004 (אופה) \u0003שהוא עושה\u0004 את הלחם \u0003בטומאה\u0004 — \u0003לא לשין ולא עורכין\u0004 (מסדרים העיסה לצורת לחם) \u0003עמו,\u0004 שלא לסייע לעבירה, \u0003אבל מוליכין עמו פת לפלטר\u0004 (למוכר הלחם).","\u0003אמר רב הונא: יין כיון שהתחיל להמשך\u0004 שהמשקה היוצא מן הענבים שבגת נמשך והולך לכיוון היציאה, אם נגע בו גוי, \u0003עושה יין נסך.\u0004 ומקשים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003לוקחים גת בעוטה מן הנכרי\u0004 שדרך בה ענבים, \u0003ואף על פי שנטל בידו\u0004 ענבים שנדרכו \u0003ונתן לתפוח\u0004 (ערימת הענבים). והרי מן הסתם כבר נמשך היין לאחר שדרכו אותו! \u0003אמר רב הונא:\u0004 מדובר \u0003בגת פקוקה ומלאה\u0004 שאין היין נמשך בה למקום אחר.","ומקשים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ששנינו: \u0003ואינו עושה יין נסך עד שירד לבור,\u0004 משמע שלפני כן אין הגוי עושה את המשקה יין נסך, למרות שנמשך בגת! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בגת פקוקה ומלאה,\u0004 שלא נמשך היין.","ועוד מציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 קושיה על רב הונא ממה ששנינו: \u0003ירד לבור, מה שבבור אסור והשאר מותר,\u0004 אף שבודאי כבר נמשך! \u0003אמר רב הונא, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 משנתנו היא לפי השיטה \u0003במשנה ראשונה, כאן\u0004 פסק ההלכה שלי הוא \u0003במשנה אחרונה;\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003בראשונה היו אומרים\u0004 בהלכות אלה, לפי הסימן \u0003בד\"ד: אין בוצרין\u0004 ענבים \u0003עם הנכרי ב\u0004שביל להביאם ל\u0003גת,\u0004 מפני \u0003שאסור לגרום טומאה לחולין שבארץ ישראל; ואין דורכין עם ישראל שעושה פירותיו בטומאה, שאסור לסייע ידי עוברי עבירה\u0004 במלאכתם; \u0003אבל דורכים עם הנכרי בגת, ו\u0004טעם הדבר ש\u0003לא חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003ל\u0004דבריו של \u0003רב הונא\u0004 שהיין הוא כבר יין נסך משעה שהתחיל להימשך.","\u0003וחזרו לומר דב\"ד: אין דורכין עם הנכרי בגת, משום\u0004 דבריו של \u0003רב הונא\u0004 לפי שבדרך כלל היין נמשך בגת בזמן הדריכה, והגוי נוגע בו ונעשה יין נסך, ונמצא הדורך עם הנכרי ונוטל על כך שכר, משתכר באיסורי הנאה."],["\u0003ואין בוצרין עם ישראל שעושה פירותיו בטומאה,\u0004 משום שבכך הוא גורם טומאה למאכל. \u0003וכל שכן שאין דורכין,\u0004 שאז הלה מטמא את המשקה על ידי הדריכה, והוא מסייע בידו. וכל זה בשל ישראל, \u0003אבל בוצרין עם הנכרי בגת,\u0004 לפי \u0003שמותר לגרום טומאה לחולין שבארץ ישראל.\u0004","שנינו במשנה: \u0003ואינו עושה יין נסך עד שירד לבור.\u0004 ומקשים: טעם הדבר הוא משום שזהו השלב בו הוא כבר קרוי יין, \u0003ו\u0004אולם \u0003התניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005]\u0006 בהגדרת גמר מלאכה של יין, כדי להתחייב במעשר: \u0003יין\u0004 — \u0003משיקפה\u0004 כלומר, שהוצף מלמעלה, שהחרצנים צפים על גבי המיץ!","\u0003אמר רבא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' עקיבא, הא רבנן\u0004 \u0005[זו\u0006 כשיטת \u0005חכמים],\u0006 \u0003דתנן\u0004 \u0005[ששנינו]:\u0006 \u0003יין\u0004 מתחייב במעשר \u0003משירד לבור, ר' עקיבא אומר: משיקפה,\u0004 משמע שנחלקו בכך, ומשנתנו שיטת חכמים היא.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לתלמידים\u0005]:\u0006 כשהוא אומר \"שיקפה\", האם הכוונה ל\u0003קיפוי\u0004 של \u0003בור\u0004 שצפים הגרעינים על היין שבבור, \u0003או קיפוי\u0004 של \u0003חבית,\u0004 שהשמרים צפים על גבי היין?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003יין\u0004 מתחייב במעשר — \u0003משיקפה.\u0004 ומכל מקום \u0003אף על פי שקפה, קולט\u0004 יין \u0003מן הגת העליונה ומן הצינור\u0004 המחבר בין הגת העליונה והתחתונה (הבור) \u0003ושותה\u0004 אף בלי לעשר. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003קיפוי\u0004 של \u0003בור קאמרינן\u0004 \u0005[אומרים אנו],\u0006 ולא הקיפוי של חבית, שהרי מכאן עולה שהיין שבגת התחתונה (הבור) אסור לו. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","על המחלוקת שהובאה בין ר' עקיבא וחכמים, מקשים: \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רב זביד ב\u0004ברייתא \u0003דבי\u0004 \u0005[\u0006מ\u0005בית מדרשו]\u0006 של \u0003ר' אושעיא: יין\u0004 מתחייב במעשר \u0003משירד לבור ויקפה, ר' עקיבא אומר: משישלה\u0004 את היין מן הבור \u0003בחביות!\u0004 ואומרים: כיון שיש בידינו שתי גרסות למחלוקת זו, מסתבר שאינן סותרות, ולפיכך \u0003תרצה נמי להך קמייתא הכי\u0004 \u0005[יישב גם כן את זו הראשונה כך]:\u0006 \u0003יין\u0004 — \u0003משירד לבור ויקפה, ר' עקיבא אומר: משישלה בחביות.\u0004","ושואלים: \u0003ואלא\u0004 לפי זה, \u0003מתניתין דקתני\u0004 \u0005[משנתנו ששנה\u0006 בה\u0005]:\u0006 \u0003אינו עושה יין נסך עד שירד לבור, לימא תלתא תנאי היא\u0004 \u0005[האם לומר\u0006 שיש פה \u0005שלוש\u0006 שיטות \u0005תנאים]\u0006 החולקים בענין זה, ממתי נגמרת מלאכת מיץ הענבים והוא קרוי יין? ודוחים: \u0003לא, שאני\u0004 \u0005[שונה]\u0006 \u0003יין נסך, דאחמירו ביה רבנן\u0004 \u0005[שהחמירו בו חכמים]\u0006 ואסרוהו עוד לפני קיפוי. אבל לענין מעשר סבור תנא זה או כדעת חכמים או כר' עקיבא."],["ומעירים: \u0003ולרבא דלא שאני ליה\u0004 \u0005[שאין שונה לו]\u0006 יין נסך, ואינו מחמיר בו יותר מדין מעשר, שהרי לעיל תירץ את הסתירה בין משנתנו לבין המשנה במעשרות כשתי שיטות שונות באותו ענין עצמו, \u0003מוקים ליה כתלתא תנאי\u0004 \u0005[\u0006הוא אכן \u0005מעמיד\u0006 ענין \u0005זה\u0006 של גמר מלאכה ביין \u0005ב\u0006מחלוקת של \u0005שלושה תנאים].\u0006","שנינו במשנה: ירד היין לבור, \u0003מה שבבור אסור והשאר מותר. אמר רב הונא: לא שנו אלא שלא החזיר גרגותני\u0004 (הסל הגדול שמסננים בו את היין בדרכו מן הגת לבור) \u0003לגת, אבל החזיר גרגותני לגת\u0004 — \u0003אסור\u0004 גם מה שנשאר בגת, שהיין שבתוכה אוסר את היין שבגת.","ושואלים: \u0003גרגותני גופה\u0004 \u0005[עצמה],\u0006 היין שבתוכה, \u0003במאי קא מיתסרא\u0004 \u0005[במה היא נאסרת]?\u0006 \u0003בנצוק\u0004 כלומר, הזרם שיורד מן הגרגותני אל הבור נחשב כיוצר חיבור בין היין שבגרגותני ליין נסך שבבור. אם כן, \u0003שמע מינה\u0004 \u0005[\u0006האם \u0005נלמד מכאן]\u0006 ש\u0003נצוק\u0004 אף הוא נקרא \u0003חיבור?\u0004 ודוחים: אפשר לפרש כי היין שבגרגותני לא נאסר בנצוק, אלא \u0003כדתני\u0004 \u0005[כמו ששנה]\u0006 \u0003ר' חייא\u0004 שיין שבמשפך נאסר במקרה \u0003שפחסתו צלוחיתו,\u0004 שהיין שבצלוחית עלה והגיע עד למשפך, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 תפרש \u0003שפחסתו בורו\u0004 כלומר, שהיין שבבור נגע ממש בגרגותני, ולכן הוא נאסר.","מסופר, \u0003ההוא ינוקא דתנא\u0004 \u0005[ילד אחד ששנה]\u0006 מסכת \u0003עבודה זרה בשית שני\u0004 \u0005[\u0006כשהיה \u0005בן שש שנים],\u0006 שהיה מופלא בכשרונותיו, \u0003בעו מיניה\u0004 \u0005[שאלו אותו]:\u0006 \u0003מהו לדרוך עם הנכרי בגת? אמר להו\u0004 \u0005[להם]:\u0006 \u0003דורכין עם הנכרי בגת,\u0004 כפי ששנינו במשנתנו. שאלוהו: \u0003והא קא מנסך בידיה\u0004 \u0005[והרי הוא מנסך בידיו]\u0006 מן היין, ונמצא שהיין יין נסך, וישראל נהנה ממנו, שמשתכר על ידו! השיב להם: \u0003דציירנא להו לידיה\u0004 \u0005[שאנו קושרים את ידיו],\u0006 שלא יוכל לנסך. והקשו: \u0003והא קא מנסך\u0004 \u0005[והרי הוא מנסך]\u0006 \u0003ברגל!\u0004 והשיב: \u0003ניסוך\u0004 של \u0003רגל לא שמיה\u0004 \u0005[אין שמו\u0006 נקרא\u0005]\u0006 \u0003ניסוך.\u0004","מסופר, \u0003ההוא עובדא דהוה\u0004 \u0005[מעשה שהיה]\u0006 \u0003בנהרדעא, דדשו\u0004 \u0005[שדרכו]\u0006 \u0003ישראל וגוי לההוא חמרא\u0004 \u0005[ליין],\u0006 \u0003ושהייה\u0004 \u0005[והשהה]\u0006 \u0003שמואל\u0004 את הבעיה \u0003תלתא ריגלי\u0004 \u0005[שלושה רגלים],\u0006 שהיו חכמים באים אז, כדי שיוכל לברר את הענין. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שהשהה את הבעיה הזו ולא פתרה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דקסבר\u0004 \u0005[שהיה סבור]:\u0006"],["\u0003דאי משכחנא\u0004 \u0005[שאם אמצא]\u0006 \u0003תנא דאסר\u0004 \u0005[שאוסר]\u0006 \u0003כר' נתן,\u0004 הסבור שיין שנגע בו גוי אסור בהנאה, \u0003אוסריניה\u0004 \u0005[אאסור]\u0006 את היין הזה \u0003אפילו בהנאה.\u0004 והיכן נאמרו דבריו של ר' נתן? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מדדו\u0004 הגוי ליין של ישראל, \u0003בין\u0004 שמדדו \u0003ביד בין ברגל\u0004 — \u0003ימכר, ר' נתן אומר:\u0004 אם מדדו \u0003ביד\u0004 — \u0003אסור, ברגל\u0004 — \u0003מותר.\u0004","על כך יש לשאול: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' נתן\u0004 שהיין נאסר בהנאה, כשנגע בו הגוי \u0003ביד,\u0004 אבל אם נגע בו \u0003ברגל מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004 הרי אף ר' נתן אינו אוסרו בהנאה! \u0003אלא\u0004 זה היה הטעם שהשהה שמואל את הבעיה, סבור היה: \u0003דאי משכחנא\u0004 \u0005[שאם אמצא]\u0006 עוד \u0003תנא דשרי\u0004 \u0005[שמתיר]\u0006 \u0003כ\u0004דעת \u0003ר' שמעון,\u0004 שמתיר יין שנגע בו גוי בלי כוונה לנסך, \u0003אישרייה\u0004 \u0005[אתיר]\u0006 את היין הזה \u0003אפילו בשתייה.\u0004","ובענין זה מסופר, \u0003ההוא עובדא דהוה\u0004 \u0005[מעשה היה]\u0006 \u0003ב\u0004מקום ששמו \u0003בירם, דההוא גוי דהוה קא סליק בדיקלא ואייתי לוליבא\u0004 \u0005[שגוי אחד היה עולה בדקל והביא\u0006 איתו \u0005לולב],\u0006 \u0003בהדי דקא נחית נגע בראשה דלוליבא בחמרא\u0004 \u0005[בתוך כדי שירד מן הדקל נגע בראש הלולב ביין]\u0006 \u0003שלא בכוונה, שרייה\u0004 \u0005[התיר אותו]\u0006 \u0003רב לזבוניה\u0004 \u0005[למוכרו]\u0006 \u0003לגוים.\u0004","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא ורב אסי לרב, והא מר\u0004 \u0005[והרי אדוני]\u0006 \u0003הוא\u0004 ש\u0003אמר:\u0004 אפילו \u0003תינוק בן יומו\u0004 (שוודאי אין בו כוונה) \u0003הוא עושה יין נסך! אמר להו\u0004 \u0005[להם]:\u0006 \u0003אימור דאמרי אנא\u0004 \u0005[אמור שאמרתי אני]\u0006 שהתינוק עושה אותו יין נסך לאסור אותו \u0003בשתייה,\u0004 לאוסרו \u0003ב\u0004איסור \u0003הנאה מי אמרי\u0004 \u0005[האם אמרתי]?\u0006 ולכן מותר למוכרו.","\u0003גופא\u0004 \u0005[לגופו]\u0006 של דבר, ש\u0003אמר רב: תינוק בן יומו עושה יין נסך.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב שימי בר חייא לרב\u0004 ממה ששנינו בברייתא: \u0003הלוקח\u0004 (הקונה) \u0003עבדים מן הגוים, שמלו ולא טבלו\u0004 עדיין, ואינם נחשבים עוד כמגויירים, \u0003וכן בני השפחות,\u0004 שגדלו בבית ישראל, \u0003שמלו ולא טבלו\u0004 — \u0003רוקן ומדרסן בשוק טמא,\u0004 שהם נחשבים כגוים ומטמאים כזבים ברוק ובמדרס, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003טהור.\u0004","ולגבי \u0003יינן\u0004 — \u0003גדולים\u0004 שבהם \u0003עושים יין נסך, קטנים אין עושים יין נסך, ואלו הן גדולים ואלו הן קטנים? גדולים\u0004 — הם אלה ש\u0003יודעין בטיב עבודה זרה ומשמשיה, קטנים\u0004 — אלה ש\u0003אינם יודעין בטיב עבודה זרה ומשמשיה.\u0004","\u0003קתני מיהת\u0004 \u0005[שנה על כל פנים]\u0006 ש\u0003גדולים\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 עושים יין נסך, \u0003קטנים\u0004 — \u0003לא,\u0004 בניגוד לדברי רב! ומשיבים: \u0003תרגמה\u0004 \u0005[תרגם,\u0006 הסבר זאת\u0005]\u0006 דווקא לגבי \u0003בני שפחות,\u0004 שאם קטנים הם, כיון שגדלו בבית ישראל אין לחשוש להם כל כך ליין נסך, ואין הדין כן בעבד של גוי.","ושואלים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"וכן\" קאמר\u0004 \u0005[אמר],\u0006 כלומר שדין בני שפחות כדין עבדים! ומשיבים: לגבי \u0003רוקן ומדרסן\u0004 אמרו, שלענין זה דינם שווה.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שרוקן ומדרסן \u0003טמא,\u0004 לומר שאף בני השפחות דינם כן, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003טהור מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי אם בשל עבדי גוים הוא טהור, כל שכן שיהא הדין כן בבני שפחות, ואין צריך לאומרו! אלא בוודאי לענין יינם נאמר.","ומשיבים: גם אם לענין יינם נאמרה השוואה זו, יש להסביר כי \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו],\u0006 ש\u0003עבדים\u0004 דינם \u0003דומיא\u0004 \u0005[דומה]\u0006 ל\u0003בני שפחות, מה בני שפחות\u0004 דווקא \u0003מלו ולא טבלו הוא\u0004 ש\u0003עושין יין נסך,\u0004 אבל אם \u0003מלו וטבלו לא, אף עבדים כן,\u0004 אחרי שמלו וטבלו אין עושים יין נסך.","ובא הדבר \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003רב נחמן\u0004 ש\u0003אמר\u0004 בשם \u0003שמואל,\u0004 ש\u0003אמר רב נחמן אמר שמואל: הלוקח עבדים מן הגוים, אף על פי ש\u0004אלה \u0003מלו וטבלו\u0004 — עדיין \u0003עושין יין נסך,\u0004 משום שעדיין יש להם הרגלים של עבודה זרה, \u0003עד שתשקע\u0004 (תיעלם) \u0003עבודה זרה מפיהם, קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003לא,\u0004 שאין הדבר כן.","\u0003גופא\u0004 \u0005[\u0006ודנים \u0005לגופה]\u0006 של הלכה זו, \u0003אמר רב נחמן אמר שמואל: הלוקח עבדים מן הגוים, אף על פי שמלו וטבלו\u0004 — \u0003עושין יין נסך עד שתשקע עבודה זרה מפיהם. וכמה\u0004 שיעורו של דבר זה? \u0003אמר ר' יהושע בן לוי: עד שנים עשר חדש.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבה לרב נחמן\u0004 ממה ששנינו בברייתא שהובאה לעיל: \u0003הלוקח עבדים מן הגוים שמלו ולא טבלו, וכן בני השפחות שמלו ולא טבלו\u0004 — \u0003רוקן ומדרסן\u0004"],["\u0003בשוק טמא, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 שהוא \u0003טהור. יינן\u0004 — \u0003גדולים עושין יין נסך, קטנים אין עושין יין נסך. אלו הן גדולים ואלו הן קטנים? גדולים\u0004 — \u0003שיודעין בטיב עבודה זרה ומשמשיה, קטנים\u0004 — \u0003שאין יודעין בטיב עבודה זרה ומשמשיה.\u0004","ונדייק: \u0003קתני מיהת\u0004 \u0005[שנה על כל פנים]\u0006 \u0003מלו ולא טבלו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 עושים יין נסך, אבל אם \u0003מלו וטבלו\u0004 — \u0003לא,\u0004 ואין צורך להמתין עוד עד שתשקע עבודה זרה מהם! ומשיבים: \u0003תרגמה\u0004 \u0005[תרגם,\u0006 הסבר\u0005]\u0006 דין יין נסך שבברייתא רק לענין \u0003בני שפחות\u0004 שגדלו בתוך בית של ישראל, שאין שם עבודה זרה מצוי בפיהם.","ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"וכן\u0004 בני השפחות\" \u0003קתני\u0004 \u0005[שנה],\u0006 משמע שדיניהם שווים לכל מה שנאמר בברייתא! ודוחים: לא לכל דבר הושוו אלא רק לענין \u0003רוקן ומדרסן.\u0004","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שרוקן ומדרסן \u0003טמא,\u0004 לומר שאפילו בני שפחות מטמאים, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שרוקן ומדרסן \u0003טהור, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי דבר זה מובן מאליו, ואין צורך לאומרו! אלא בוודאי לענין יינם נאמר.","ומשיבים: גם אם לענין יינם נאמר, עדיין יש להבין כי \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]\u0006 ש\u0003עבדים דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003בני שפחות, מה בני שפחות\u0004 — \u0003גדולים הוא\u0004 ש\u0003עושין יין נסך, קטנים אין עושין יין נסך, אף עבדים נמי\u0004 \u0005[גם כן]\u0006 — דווקא \u0003גדולים עושין יין נסך,\u0004 אבל \u0003קטנים אין עושין יין נסך,\u0004 ובא הדבר","\u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003רב,\u0004 ש\u0003אמר רב: תינוק בן יומו עושה יין נסך, קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003לא.\u0004","מסופר, \u0003ההוא עובדא דהוה\u0004 \u0005[מעשה שהיה]\u0006 \u0003במחוזא, אתא\u0004 \u0005[בא]\u0006 \u0003גוי עייל לחנותא\u0004 \u0005[נכנס לחנות]\u0006 של \u0003ישראל, אמר להו\u0004 \u0005[להם]:\u0006 \u0003אית לכו חמרא לזבוני\u0004 \u0005[יש לכם יין למכור]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לא, הוה יתיב חמרא בדוולא\u0004 \u0005[היה יושב,\u0006 מונח \u0005יין בתוך דלי],\u0006 \u0003שדי ביה ידיה שיכשך ביה\u0004 \u0005[הניח בו\u0006 הגוי \u0005ידו\u0006 ו\u0005שיכשך בו],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003האי לאו חמרא הוא\u0004 \u0005[\u0006האם \u0005זה אינו יין]?\u0006 \u0003שקליה האיך בריתחיה שדייה לדנא\u0004 \u0005[לקח הלה,\u0006 בעל החנות, \u0005בכעסו\u0006 את דלי היין ו\u0005שפכו לחבית],\u0006 ועלתה השאלה לפני חכמים מה דינו של היין שבחבית,","\u0003שרייה\u0004 \u0005[התיר]\u0006 \u0003רבא לזבוני\u0004 \u0005[למכור]\u0006 \u0003לגוים\u0004 את היין, שלדעתו אינו אסור בהנאה. \u0003איפליג עליה\u0004 \u0005[נחלקו עליו]\u0006 \u0003רב הונא בר חיננא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן. נפקי שיפורי\u0004 \u0005[יצאו שופרות]\u0006 מבית דינו של \u0003רבא\u0004 להכריז את הדין \u0003ושרו\u0004 \u0005[והתירו],\u0006 \u0003ונפקי שיפורי\u0004 \u0005[ויצאו שופרות]\u0006 מבית דינו של \u0003רב הונא בר חיננא ורב הונא בר רב נחמן ואסרי\u0004 \u0005[ואסרו].\u0006"],["ובענין זה מסופר, \u0003איקלע\u0004 \u0005[נזדמן]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן ל\u0004עיר \u0003מחוזא, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב אליקים שמעיה\u0004 \u0005[שמשו]:\u0006 \u0003טרוק טרוק גלי\u0004 \u0005[סגור סגור השערים],\u0006 כדי ש\u0003לא ניתו אינשי דניטריד\u0004 \u0005[יבואו אנשים שיטרידו\u0006 אותנו\u0005]\u0006 ונוכל לברר ענין במנוחה.","\u0003על לגביה\u0004 \u0005[נכנס אליו]\u0006 רב הונא בר נחמן, \u0003אמר ליה\u0004 \u0005[לו]\u0006 לרבא: \u0003כי האי גוונא מאי\u0004 \u0005[כגון זה,\u0006 ששיכשך גוי ביין שלא לשם ניסוך, \u0005מהו,\u0006 מה דינו\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אסור\u0004 יין זה \u0003אפילו בהנאה.\u0004 והקשה לו: \u0003והא מר\u0004 \u0005[והרי אדוני]\u0006 \u0003הוא\u0004 ש\u0003אימר\u0004 \u0005[\u0006ש\u0005אמר]\u0006 \u0003שיכשך\u0004 הגוי \u0003אין עושה יין נסך,\u0004 כשהתרת למכור את היין שבחבית לגוים! ענה לו רבא: \u0003אימר דאמרי אנא לבר מדמיה דההוא חמרא\u0004 \u0005[אמור שאמרתי אני\u0006 שמותר למכור את היין שבחבית וליהנות מדמיו \u0005חוץ מדמיו של אותו יין\u0006 אסור\u0005]\u0006 שנשפך לחבית, ואולם \u0003דמי דההוא חמרא מי אמרי\u0004 \u0005[דמי אותו יין האם אמרתי]?\u0006 לא התרתי אלא למכור החבית בניכוי דמי אותו יין.","ועוד בענין זה, \u0003אמר רבא: כי אתאי\u0004 \u0005[כאשר הגעתי]\u0006 \u0003לפומבדיתא, אקפן נחמני שמעתתא ומתניתא דאסיר\u0004 \u0005[הקיף אותו נחמני,\u0006 הוא אביי, \u0005בשמועות\u0006 מפי אמוראים, \u0005וברייתות ש\u0006יין ששכשך בו הגוי \u0005אסור]\u0006 אפילו בהנאה.","והוא מפרט: \u0003שמעתתא\u0004 \u0005[שמועות],\u0006 \u0003דההוא עובדא דהוה\u0004 \u0005[מעשה\u0006 כזה \u0005שהיה]\u0006 \u0003בנהרדעא ואסר שמואל,\u0004 וכן מעשה כזה שהיה \u0003בטבריא ואסר ר' יוחנן. ואמרי ליה\u0004 \u0005[ואמרתי לו]\u0006 לאביי, שהטעם שאסרו שם היה \u0003לפי ש\u0004בני עריהם \u0003אינן בני תורה,\u0004 והוצרכו שמואל ור' יוחנן לגודרם במיוחד. \u0003ואמר לי\u0004 בתמיהה: אנשי \u0003טבריא ונהרדעא אינן בני תורה,\u0004 אנשים של העיר \u0003מחוזא\u0004 שפסקת שם להיתר \u0003בני תורה\u0004 הם? ואפילו אם מטעם זה היה לך לאסור.","\u0003מתניתא\u0004 \u0005[הברייתות]\u0006 שהקשה לי אביי מהם, ששנינו: \u0003אגרדמים\u0004 (ממונה על מידות ומחירים בשוק) \u0003גוי שקדח\u0004 חור בחבית \u0003במינקת\u0004 (כעין צינור) \u0003והעלה\u0004 בה יין לטעימה, \u0003או שטעם מן הכוס\u0004 שמזגו לו \u0003והחזירו לחבית, זה היה מעשה ואסרוהו; מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שאסרוהו \u0003בהנאה?\u0004 והשבתי לו: \u0003לא,\u0004 הכוונה שאסרו רק \u0003בשתייה.\u0004","הקשה אביי: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003ימכר, כדקתני סיפא\u0004 \u0005[כמו ששנה בסוף]\u0006 אותה ברייתא: \u0003חרם\u0004 (אנס, הלוקח דברים בכוח) \u0003גוי שהושיט ידו לחבית, וכסבור של שמן היא ונמצאת\u0004 שהיתה חבית \u0003של יין, זה היה מעשה ואמרו: ימכר,\u0004 שכיון שחשב שזו חבית שמן לא הניח ידו בה לשם יין כלל! ומעירים: \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 על \u0003רבא,\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","מסופר \u0003ר' יוחנן בן ארזא ור' יוסי בן נהוראי הוו יתבו וקא שתו חמרא\u0004 \u0005[היו יושבים ושותים יין],\u0006 \u0003אתא ההוא גברא\u0004 \u0005[בא אדם אחד],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003תא אשקינן\u0004 \u0005[בוא השקה אותנו],\u0006 \u0003לבתר דרמא לכסא איגלאי מילתא\u0004 \u0005[לאחר שמזג לכוס התגלה הדבר]\u0006 ש\u0003גוי הוא,\u0004 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אסר\u0004 את היין \u0003אפילו בהנאה, וחד שרי\u0004 \u0005[ואחד התיר]\u0006 \u0003אפילו בשתייה. אמר ר' יהושע בן לוי: מאן\u0004 \u0005[מי]\u0006 ש\u0003אסר שפיר\u0004 \u0005[יפה]\u0006 \u0003אסר, ומאן דשרי שפיר שרי\u0004 \u0005[ומי שהתיר יפה התיר],\u0006 שיש לכל אחד מהם טעם הגון לדבריו. והוא מסביר את דבריו שלכאורה יש בהם סתירה: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אסר\u0004 מה טעמו?"],["סבור היה כי \u0003מימר אמר\u0004 \u0005[אומר\u0006 הגוי בליבו\u0005]:\u0006 \u0003סלקא דעתיה דרבנן כי הני שיכרא קא שתו\u0004 \u0005[\u0006וכי \u0005יעלה על דעתך שחכמים\u0006 חשובים \u0005כאלה שיכר הם שותים]?\u0006 \u0003אלא ודאי האי חמרא\u0004 \u0005[זה יין]\u0006 \u0003הוא\u0004 \u0003ונסכיה\u0004 \u0005[וניסך אותו].\u0006 \u0003מאן דשרי שפיר שרי\u0004 \u0005[מי שהתיר יפה התיר],\u0006 סבור היה כי \u0003מימר אמר\u0004 \u0005[אומר\u0006 הגוי בליבו\u0005]:\u0006 \u0003סלקא דעתך דרבנן כי הני חמרא קא שתו\u0004 \u0005[\u0006וכי \u0005יעלה על דעתך שחכמים כאלה יין הם שותים],\u0006 \u0003ואמר ליה לדידי \"תא אשקינן\"\u0004 \u0005[ו\u0006הם \u0005אומרים לי,\u0006 שאני גוי, \u0005\"בוא והשקה אותנו\u0006 מן היין\"\u0005]?\u0006 \u0003אלא ודאי שיכרא הוא קא שתו\u0004 \u0005[שיכר הוא שהם שותים]\u0006 \u0003ולא נסכיה\u0004 \u0005[ניסכו].\u0006","ומקשים: \u0003והא קא חזי\u0004 \u0005[והרי הוא רואה]\u0006 אם יין הוא או שיכר! ומשיבים: מעשה זה זה היה \u0003בליליא\u0004 \u0005[בלילה].\u0006 ושואלים: \u0003והא קא מרח ליה\u0004 \u0005[והרי הוא מריח אותו]\u0006 ויודע שהוא יין! ומשיבים: מדובר היה \u0003בחדתא\u0004 \u0005[ב\u0006יין \u0005חדש]\u0006 שאין ריחו נודף.","ושואלים: ולמרות זאת, מי שהתיר כיצד התיר? \u0003והא קא נגע ביה\u0004 \u0005[והרי הוא נגע בו]\u0006 כששאב אותו מן החבית \u0003בנטלא\u0004 \u0005[בספל],\u0006 \u0003והוה ליה\u0004 \u0005[והריהו]\u0006 \u0003מגע גוי שלא בכוונה ואסור!\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא משום שמדובר היה במקרה \u0003דקא מוריק אורוקי\u0004 \u0005[שהוא רק מריק\u0006 מכלי לכלי\u0005],\u0006 בלא לנגוע כלל ביין, \u0003והוה ליה\u0004 \u0005[והרי זה]\u0006 \u0003כחו\u0004 של גוי ששופך את היין, ועושה זאת \u0003שלא בכוונה, וכל כחו שלא בכוונה לא גזרו ביה רבנן\u0004 \u0005[בו חכמים]\u0006 כל איסור, אפילו בשתיה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אסי מר' יוחנן: יין שמסכו\u0004 (שמזג בו מים) \u0003גוי, מהו? אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן, \u0003ואימא\u0004 \u0005[ואמור]\u0006 את השאלה בלשון הרגילה: \u0003\"מזגו\",\u0004 מדוע אומר אתה \"מסכו\"? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא כדכתיב קאמינא\u0004 \u0005[אני כמו\u0006 לשון \u0005הכתוב אני אומר],\u0006 שנאמר: \u0003\"טבחה טבחה מסכה יינה\"\u0004 (משלי ט, ב). \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אכן, לשון מקרא כך היא, אבל \u0003לשון תורה לעצמה, לשון חכמים לעצמו,\u0004 ואין לערבב.","ולגופו של דבר שאל ר' אסי: \u0003מאי\u0004 \u0005[מה]\u0006 ההלכה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אסור\u0004 הדבר, \u0003משום\u0004 הפתגם שאומרים: \u0003\"לך לך אמרין נזירא, סחור סחור, לכרמא לא תקרב\"\u0004 \u0005[לך לך אומרים, לנזיר, סביב סביב, לכרם אל תקרב].\u0006 כלומר, אף שאינו אסור מצד עיקר הדין, ענין של הרחקה הוא.","וכן מסופר, \u0003ר' ירמיה איקלע לסבתא\u0004 \u0005[הזדמן לבית מרזח],\u0006 \u0003חזא חמרא דמזגי\u0004 \u0005[\u0006ו\u0005ראה יין שמוזג]\u0006 \u0003גוי ואישתי ישראל מיניה\u0004 \u0005[ושותה יהודי ממנו],\u0006 \u0003ואסר להו\u0004 \u0005[להם]\u0006 \u0003משום \"לך לך אמרין נזירא, סחור סחור, לכרמא לא תקרב\"\u0004 \u0005[לך לך אומרים, לנזיר, סביב סביב, לכרם אל תקרב].\u0006 \u0003אתמר נמי\u0004 \u0005[נאמר גם כן]:\u0006 \u0003אמר ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003אמר ר' אסי אמר ר' יוחנן: יין שמזגו גוי\u0004 — \u0003אסור, משום \"לך לך אמרין נזירא, סחור סחור, לכרמא לא תקרב\"\u0004 \u0005[לך לך אומרים, לנזיר, סביב סביב, לכרם אל תקרב].\u0006","אגב המעשה בר' ירמיה שנקלע למקום ואסר עליהם דבר, מסופר: \u0003ריש לקיש איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004עיר \u0003בצרה\u0004 בעבר הירדן, \u0003חזא ישראל דקאכלי פירי דלא מעשרי\u0004 \u0005[ראה יהודים שאוכלים פירות שאינם מעושרים]\u0006 \u0003ואסר להו\u0004 \u0005[להם],\u0006 \u0003חזא מיא דסגדי להו גוים ושתו ישראל\u0004 \u0005[ראה מים שמשתחווים להם הגוים ושותים יהודים]\u0006 \u0003ואסר להו\u0004 \u0005[להם].\u0006","\u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' יוחנן\u0004 וסיפר לו את המעשה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אדמקטורך עלך זיל הדר\u0004 \u0005[עד שמעילך עליך לך החזר\u0006 את הדין\u0005],\u0006 והתר להם לאכול פירות בלא לעשרם, כי \u0003בצר\u0004 המנויה במקרא (דברים ד, מג) בין ערי המקלט \u0003לאו היינו\u0004 \u0005[אין היא]\u0006 \u0003בצרה,\u0004 ובצרה אינה ארץ ישראל ולכן אין חובה לעשר בה. \u0003ו\u0004התר להם לשתות את המים, כי \u0003מים של רבים אין נאסרין.\u0004","ומעירים: \u0003ר' יוחנן לטעמיה\u0004 \u0005[\u0006הולך \u0005לשיטתו]\u0006 בענין זה,"],["ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יהוצדק: מים של רבים אין נאסרין.\u0004 ומעירים: מדברי ר' יוחנן יש להבין כי \u0003הא\u0004 \u0005[אבל]\u0006 במקרה כזה, אם היו המים של \u0003יחיד\u0004 היו \u0003נאסרין.\u0004","ותוהים: \u0003ותיפוק ליה\u0004 \u0005[ושתצא לו]\u0006 הלכה זו שאינם נאסרים, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003מחוברין נינהו\u0004 \u0005[הם],\u0006 ומחובר שעבדוהו אינו נאסר! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא במקום \u0003דתלשינהו גלא\u0004 \u0005[שתלשם הגל]\u0006 למקצת המים, ונעקרו מחיבורם, ובמקרה זה אם היו של יחיד היו נאסרים.","ודוחים: \u0003סוף סוף\u0004 הרי בגדר של \u0003אבני הר שנדלדלו\u0004 מעצמן מן ההר \u0003נינהו\u0004 \u0005[הם],\u0006 שנחלקו ר' יוחנן ובני ר' חייא (מו,א) באבנים כאלה, שלא היתה בהן תפיסת יד אדם, האם הן נאסרות כשנעבדו כעבודה זרה או לא, ולא נתברר בגמרא מה סבור כל אחד מהם. ואם כן \u0003תסתיים\u0004 \u0005[תוגדר,\u0006 יתברר מכאן\u0005]\u0006 ש\u0003ר' יוחנן\u0004 הוא ש\u0003אמר\u0004 שאבני הר אלה \u0003אסורות?\u0004","ודוחים: עדיין יש לומר כי \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו של ר' יוחנן אלא במקרה \u0003דטפחינהו בידיה\u0004 \u0005[שטפח בהם,\u0006 במים הללו \u0005בידיו].\u0006 שלא מעצמם נתלשו, כמו אבני הר שנדלדלו, אלא במגע ידי אדם, ואם היו של יחיד היו נאסרים.","בדומה למעשה האחרון, ובענין יין שמזגוהו גוים, מסופר: \u0003ר' חייא בר אבא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004יישוב \u0003גבלא, חזא\u0004 \u0005[ראה]\u0006 שם בנות ישראל דמיעברן \u0005[שמעוברות]\u0006 \u0003מגוים ש\u0004עמדו להתגייר וכבר \u0003מלו ו\u0004עדיין \u0003לא טבלו, חזא חמרא דמזגו\u0004 \u0005[ראה יין שמוזגים]\u0006 \u0003גוים ושתו ישראל\u0004 \u0005[ושותים יהודים],\u0006 \u0003חזא תורמוסא דשלקי להו\u0004 \u0005[\u0006ו\u0005ראה תורמוס ששולקים,\u0006 מבשלים, \u0005אותו]\u0006 \u0003גוים ואכלי ישראל\u0004 \u0005[ואוכלים יהודים],\u0006 \u0003ולא אמר להו\u0004 \u0005[להם]\u0006 \u0003ולא מידי\u0004 \u0005[דבר]\u0006 לתקן את מעשיהם.","לאחר זמן \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' יוחנן\u0004 וסיפר לו על הדברים שראה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003צא והכרז על בניהם\u0004 של אותם גוים \u0003שהן ממזרים, ו\u0004הכרז \u0003על יינן\u0004 שאסור \u0003משום יין נסך, ו\u0004הכרז \u0003על תורמוסן\u0004 שאסור \u0003משום בישולי גוים משום שאינן בני תורה.\u0004","ומסבירים: \u0003על בניהם שהם ממזרים\u0004 — \u0003ר' יוחנן\u0004 הולך בענין זה \u0003לטעמיה\u0004 \u0005[לשיטתו],\u0006 ש\u0003אמר ר' יוחנן: לעולם אינו\u0004 נעשה ל\u0003גר עד שימול ויטבול, וכיון דלא טביל\u0004 \u0005[שאינו טובל]\u0006 — \u0003גוי הוא. ו\u0004לגבי מעמדם של הילדים, גם שם הולך ר' יוחנן לשיטתו, ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: גוי ועבד הבא על בת ישראל\u0004 — \u0003הולד\u0004 ממנה הוא \u0003ממזר.\u0004","ומה שאמר לו: \u0003וגזור על יינם משום יין נסך\u0004 — אף שאין כזה איסור בעצם, הרי הוא אסור \u0003משום \"לך לך, אמרין, נזירא, סחור סחור, לכרמא לא תקרב\"\u0004 \u0005[לך לך, אומרים לנזיר, סחור סחור, לכרם אל תקרב],\u0006 ולכן צריך להרחיק מזה.","ועל מה שאמר לו ר' יוחנן \u0003ועל תורמוסן\u0004 גזרו \u0003משום בישולי גוים, לפי שאינן בני תורה,\u0004 וצריך להרחיקם מדבר הדומה לאיסור. מדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003אינן בני תורה, הא\u0004 \u0005[אבל]\u0006 אם היו \u0003בני תורה שרי\u0004 \u0005[מותר]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב שמואל בר רב יצחק אמר רב: כל שנאכל כמות שהוא חי\u0004 — \u0003אין בו משום בישולי גוים,\u0004 אבל תורמוס, כיון שהוא מר מאד ודאי אין אוכלים אותו בעודו חי, ואם כן בכלל בישולי גוים הוא!","ומשיבים: \u0003ר' יוחנן כי הך לישנא סבירא ליה\u0004 \u0005[כלשון האחרת סבור הוא]\u0006 בענין זה, ש\u0003אמר רב שמואל בר רב יצחק אמר רב: כל שאינו עולה לשולחן של מלכים ללפת בו את הפת\u0004 — \u0003אין בו משום בישולי גוים,\u0004 והתורמוס אינו מאכל חשוב שיעלה על שולחן מלכים. ולכן, \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003אינן בני תורה\u0004 אוסרים להם, \u0003הא\u0004 \u0005[הרי]\u0006 אם היו \u0003בני תורה שרי\u0004 \u0005[מותר].\u0006","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 \u0003מרב כהנא: גוי מהו שיוליך ענבים לגת,\u0004 אף שאינו עושה בהם דבר? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אסור, משום\u0004 הטעם של \u0003\"לך לך, אמרין, נזירא, סחור סחור לכרמא לא תקרב\"\u0004 \u0005[לך לך, אומרים\u0006 \u0005לנזיר, סחור סחור, לכרם אל תקרב].\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב יימר לרב כהנא\u0004 ממה ששנינו: \u0003גוי שהביא ענבים לגת בסלין\u0004"],["\u0003ובדודורין\u0004 (חביות קטנות), \u0003אף על פי שהיין\u0004 כלומר, המיץ \u0003מזלף עליהן\u0004 משום שהם נמעכים והמיץ יוצא מהם — בכל זאת \u0003מותר! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הביא קאמרת\u0004 \u0005[אומר אתה]?\u0006 שם מדובר כאשר כבר הביא הגוי את הענבים, ודנים אם לאסור בדיעבד, \u0003אנא\u0004 \u0005[אני]\u0006 \u0003לכתחלה קאמינא\u0004 \u0005[אמרתי]\u0006 שלא יביא.","מסופר, \u0003ההוא אתרוגא דנפל לחביתא דחמרא\u0004 \u0005[אתרוג אחד נפל לחבית יין],\u0006 \u0003אידרי גוי ושקליה\u0004 \u0005[קפץ הגוי\u0006 כדי \u0005ליטול אותו\u0006 משם\u0005],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב אשי\u0004 לאנשים שהיו שם: \u0003נקטוה לידיה כי היכי דלא לשכשיך ביה\u0004 \u0005[תחזיקו את ידו כדי שלא ישכשך בו,\u0006 ביין\u0005]\u0006 ויאסור אותו, \u0003וברצוה\u0004 \u0005[והטו אותה\u0006 את החבית\u0005]\u0006 \u0003עד דשייפא\u0004 \u0005[שתתרוקן]\u0006 מן היין ואז יוכל לקחת את האתרוג.","\u0003אמר רב אשי: האי גוי דנסכיה לחמרא\u0004 \u0005[גוי שניסך את היין]\u0006 של \u0003ישראל בכוונה\u0004 כדי לאסור אותו, \u0003אף על גב דלזבוניה\u0004 \u0005[אף על פי שלמכור אותו]\u0006 \u0003לגוי אחרינא\u0004 \u0005[אחר]\u0006 \u0003אסור,\u0004 שהרי היין אסור בהנאה, ובכלל זה ליהנות מדמיו, מכל מקום \u0003שרי ליה למישקל דמיה\u0004 \u0005[מותר לו לקחת\u0006 את \u0005דמיו\u0006 של היין\u0005]\u0006 \u0003מההוא\u0004 \u0005[מאותו]\u0006 \u0003גוי, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003מיקלא קלייה\u0004 \u0005[\u0006הרי זה כאילו \u0005שרף אותו,\u0006 את היין\u0005],\u0006 והוא צריך לשלם כמזיק.","\u0003אמר רב אשי: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]\u0006 את ההלכה הזו? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003גוי שנסך יינו של ישראל שלא בפני עבודה זרה\u0004 — \u0003אסור, ור' יהודה בן בבא ור' יהודה בן בתירא מתירין משום שני דברים, אחד\u0004 — \u0003שאין מנסכין יין אלא בפני עבודה זרה, ואחד\u0004 — \u0003שאומר לו\u0004 הישראל לגוי: \u0003לא כל הימנך\u0004 \u0005[לא הכל ממך,\u0006 אין זה בכוחך\u0005]\u0006 \u0003שתאסור ייני לאונסי\u0004 שלא מרצוני, ולכן היין בעצם מותר.","\u0003ההיא חביתא דחמרא דאישתקיל לברזא\u0004 \u0005[חבית יין אחת שניטל הברז\u0006 שלה\u0005]\u0006 והיה היין נשפך ממנה, \u0003אתא\u0004 \u0005[הלך]\u0006 \u0003גוי\u0004 אחד \u0003אידרי אנח ידיה עילויה\u0004 \u0005[\u0006ו\u0005קפץ והניח את ידו\u0006 על הנקב\u0005]\u0006 כדי שלא יישפך היין, \u0003אמר רב פפא: כל דלהדי ברזא\u0004 \u0005[כל שכנגד הברז],\u0006 אותו חלק מן היין שממש נוגע בידו של הגוי, \u0003חמרא אסיר\u0004 \u0005[היין אסור],\u0006"],["\u0003ואידך שרי\u0004 \u0005[והשאר מותר].\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים],\u0006 \u0003אמר רב פפא:\u0004 מלמעלה \u0003עד\u0004 לגובה \u0003הברזא\u0004 \u0005[הברז]\u0006 — \u0003חמרא אסיר\u0004 \u0005[היין אסור],\u0006 \u0003ואידך\u0004 \u0005[והשאר]\u0006 שמתחת לברז — \u0003שרי\u0004 \u0005[מותר].\u0006","\u0003אמר רב יימר:\u0004 דבריו של רב פפא שנויים במחלוקת, \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005התנאים]\u0006 ששנינו בברייתא: \u0003חבית שנקבה, בין מפיה\u0004 (מלמעלה), \u0003בין משוליה\u0004 (בתחתיתה) \u0003ובין מצידיה, ונגע בו טבול יום\u0004 — \u0003טמאה. ר' יהודה אומר:\u0004 אם \u0003מפיה ומשוליה\u0004 ניקבה — \u0003טמאה,\u0004 אם \u0003מצידיה\u0004 — \u0003טהורה מכאן ומכאן\u0004 (ולא נטמא אלא מה שנגע בו), וכדברי רב פפא ללשון הראשונה.","\u0003אמר רב פפא: גוי\u0004 שהיה מחזיק \u0003אדנא\u0004 \u0005[בחבית]\u0006 \u0003וישראל\u0004 מחזיק \u0003אכובא\u0004 \u0005[בכלי\u0006 של יין\u0005]\u0006 והגוי שופך מן החבית לכלי — \u0003חמרא אסיר\u0004 \u0005[היין אסור],\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003כי קאתי\u0004 \u0005[כאשר בא]\u0006 — \u0003מכח גוי קאתי\u0004 \u0005[הוא בא].\u0006 ואם להיפך, \u0003ישראל\u0004 מחזיק \u0003אדנא\u0004 \u0005[את החבית]\u0006 \u0003וגוי אכובא\u0004 \u0005[מחזיק את הכלי הקטן]\u0006 והישראל שופך לכלי שמחזיק הגוי — \u0003חמרא שרי\u0004 \u0005[היין מותר].\u0006 \u0003ואי מצדד צדודי\u0004 \u0005[ו\u0006אולם \u0005אם\u0006 הגוי \u0005מצדד]\u0006 את הכובא, שמטה אותו — היין שבכלי \u0003אסיר\u0004 \u0005[נאסר].\u0006","\u0003אמר רב פפא: האי גוי דדרי זיקא\u0004 \u0005[גוי זה שנושא\u0006 על גבו \u0005נאד\u0006 יין סגור\u0005]\u0006 \u0003וקאזיל\u0004 \u0005[והולך]\u0006 \u0003ישראל אחוריה\u0004 \u0005[אחריו],\u0006 ומשגיח שלא יגע ביין עצמו, אם הנאד \u0003מליא\u0004 \u0005[מלא]\u0006 יין — הרי זה \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003דלא מקרקש\u0004 \u0005[שאין\u0006 היין \u0005מתנועע\u0006 בתוכו\u0005],\u0006 ולכן אין בזה כל איסור. אם הנאד \u0003חסירא\u0004 \u0005[חסר]\u0006 — \u0003אסיר\u0004 \u0005[אסור],\u0006 \u0003דלמא מקרקש\u0004 \u0005[שמא מתנועע\u0006 בתוכו\u0005]\u0006 היין, והרי זה כעין ניסוך. לעומת זאת \u0003כובא\u0004 (מין כלי של יין) שהוא פתוח מלמעלה, \u0003מליא\u0004 \u0005[מלא]\u0006 — \u0003אסיר\u0004 \u0005[אסור]\u0006 \u0003דלמא נגע\u0004 \u0005[שמא נוגע]\u0006 בו ביין שמגיע לשפת הכלי, אם הוא \u0003חסירא\u0004 \u0005[חסר,\u0006 שאינו מלא\u0005]\u0006 — \u0003שרי\u0004 \u0005[מותר]\u0006 ואין לחשוש בו, \u0003דלא נגע\u0004 \u0005[\u0006מפני \u0005שאינו נוגע]\u0006 ביין.","\u0003רב אשי אמר: זיקא, בין מליא ובין חסירא\u0004 \u0005[נאד, בין מלא ובין חסר]\u0006 — \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם הדבר]?\u0006 \u0003אין דרך ניסוך בכך\u0004 שאין דרך ניסוך בנענוע יין בתוך כלי סגור.","\u0003מעצרא זיירא\u0004 \u0005[גת של מכבש]\u0006 שאין דורכים בה את הענבים ברגל, אלא כובשים את הענבים על ידי לוחות או מכבש — \u0003רב פפי שרי\u0004 \u0005[התיר]\u0006 את היין אם הגוי כובש את הקורה, שהרי הוא עצמו אינו נוגע ביין, ואילו \u0003רב אשי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב שימי בר אשי אסר.\u0004","ומעירים: \u0003בכחו,\u0004 אם הכבישה היא במישרין מכוחו של הגוי, \u0003כולי עלמא לא פליגי דאסיר\u0004 \u0005[הכל אינם חלוקים שאסור],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — הרי זה \u0003בכח כחו. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת: \u0003בכח כחו כולי עלמא לא פליגי דשרי\u0004 \u0005[הכל אינם חלוקים שמותר],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 כשעושה \u0003בכחו.\u0004 מסופר, \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 שנכבש יין \u0003בכח כחו\u0004 של גוי, \u0003ואסר רב יעקב מנהר פקוד.\u0004","מסופר, \u0003ההוא חביתא\u0004"],["\u0003דאיפקעה\u0004 \u0005[שנבקעה]\u0006 \u0003לאורכה\u0004 מלמעלה למטה, \u0003אידרי ההוא גוי חבקה\u0004 \u0005[קפץ גוי\u0006 \u0005אחד\u0006 ו\u0005חיבק\u0006 אותה\u0005]\u0006 שלא תיפתח, ושהיין לא יישפך, \u0003שרייה\u0004 \u0005[התיר אותה]\u0006 \u0003רפרם בר פפא, ואי תימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע, לזבוני\u0004 \u0005[למכור\u0006 אותה\u0005]\u0006 \u0003לגוים,\u0004 שנאסרה בשתיה אבל לא בהנאה. ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים ש\u0003פקעה לאורכה, אבל\u0004 אם נבקעה \u0003לפותייה\u0004 \u0005[לרוחבה]\u0006 והגוי הידק את החלק העליון על התחתון — \u0003אפילו בשתיה\u0004 גם כן \u0003שרי\u0004 \u0005[מותרת],\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 הגוי שמחזיק את החבית רק \u0003מעשה לבינה קעביד\u0004 \u0005[עושה],\u0006 שאינו עושה מעשה ביין, אלא רק מכביד על החבית כאילו היה לבינה, או דבר כבד אחר.","מסופר, \u0003ההוא גוי דאשתכח דהוה קאי במעצרתא\u0004 \u0005[גוי אחד שנמצא עומד בתוך הגת]\u0006 עצמה, \u0003אמר רב אשי: אי איכא\u0004 \u0005[אם יש\u0006 שם יין\u0005]\u0006 בכמות כזו שהיא של \u0003טופח להטפיח\u0004 (רטוב עד כדי להרטיב דבר אחר) — \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003הדחה\u0004 של הגת במים \u0003ובעי\u0004 \u0005[ו\u0006גם \u0005צריך]\u0006 \u0003ניגוב\u0004 (ניקוי יסודי יותר. להלן עבודה זרה עד,ב), \u0003ואי\u0004 \u0005[ואם]\u0006 הוא \u0003לא\u0004 טופח להטפיח, גם אם יש שם לחות — \u0003בהדחה בעלמא סגי ליה\u0004 \u0005[בלבד די לו].\u0006","\u0003נכרי שנמצא עומד בצד הבור של יין, אם יש לו מלוה עליו\u0004 כלומר, שבעל הבור חייב כסף לגוי — \u0003אסור\u0004 היין, שאנו חוששים שכיוון שהגוי סבור שיש לו זכות בנכסיו של הלווה לא יימנע מלנגוע ביין. \u0003אין לו מלוה עליו\u0004 — \u0003מותר,\u0004 שאין אנו חוששים שהוא נוגע בדבר שאינו שלו.","\u0003נפל\u0004 הגוי \u0003לבור\u0004 יין \u0003ועלה,\u0004 או \u0003מדדו\u0004 ליין שבבור \u0003בקנה\u0004 בלי לנגוע בו בידו, או \u0003התיז את הצרעה בקנה\u0004 ונגע הקנה ביין, \u0003או שהיה מטפיח\u0004 מסיר קצף מ\u0003על פי חבית מרותחת\u0004 — \u0003בכל אלו היה מעשה ואמרו: ימכר,\u0004 שהיין מותר בהנאה אבל אסור בשתיה, \u0003ור' שמעון מתיר\u0004 אף בשתיה. \u0003נטל\u0004 הגוי \u0003את החבית\u0004 של יין \u0003וזרקה בחמתו לבור, זה היה מעשה והכשירו\u0004 אף בשתיה.","בפירוש דברי המשנה \"אם יש לו מלוה עליו\", \u0003אמר שמואל: והוא שיש לו מלוה על אותו יין\u0004 עצמו, שהיין משועבד לגביית חוב זה — אז יש לחשוש למגע הגוי ביין, שאז הוא מרגיש בעלות עליו.","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 בפירוש זה, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה הבאה\u0005]:\u0006 \u0003המטהר יינו של נכרי\u0004 ישראל הדורך ענבים של גוי כדי למכור את היין לישראל, \u0003ונותנו ברשותו\u0004 של הגוי עד שימכרנו, \u0003והלה\u0004 הגוי \u0003כותב לו: \"התקבלתי ממך מעות\"\u0004 — הרי זה \u0003מותר,\u0004 לפי שהיין נחשב כשייך לגמרי לישראל ואין לחשוש שנגע בו הגוי. \u0003אבל\u0004 והיה \u0003אם ירצה ישראל\u0004 זה \u0003להוציאו,\u0004 \u0003ואין\u0004 גוי \u0003מניחו עד שיתן לו מעותיו\u0004 (שישלם לו עבור היין), \u0003זה היה מעשה בבית שאן ואסרו.\u0004","ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003אין מניחו,\u0004 שאז אומרים שיש מעין בעלות לגוי עליו, ואז הוא אסור, \u0003הא\u0004 \u0005[אבל]\u0006 אם היה \u0003מניחו\u0004 להוציא את היין \u0003שרי\u0004 \u0005[מותר],\u0006 למרות שהישראל עדיין חייב לו מעות. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003מלוה על אותו יין בעינן\u0004 \u0005[צריכים אנו],\u0006 שרק כאשר יש לו מעין בעלות על היין, ולא חובת תשלום יש לחשוש למגעו. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה: \u0003נפל לבור ועלה\u0004 — יימכר, שאינו אסור בהנאה. \u0003אמר רב פפא: לא שנו אלא שעלה\u0004 הגוי משם \u0003מת,\u0004 שהוציאו את הגוי משם כשהוא מת, \u0003אבל\u0004 אם \u0003עלה חי\u0004 — \u0003אסור.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר רב פפא: דדמי עליה\u0004 \u0005[שדומה לו]\u0006 לגוי הדבר הזה \u0003כיום אידם\u0004 (חגם) שאירע לו נס וניצל, ובגלל שרוצה להודות לעבודה זרה בוודאי מנסך כשיוצא מן הבור.","\u0003מדדו בקנה... כל אלו היה מעשה ואמרו: ימכר, ור' שמעון מתיר. אמר רב אדא בר אהבה: ינוחו לו לר' שמעון ברכות על ראשו,\u0004 מפני ששיטתו היא שיטה חד משמעית, \u0003כשהוא מתיר\u0004 — \u0003מתיר אפילו בשתיה, וכשהוא אוסר\u0004 — \u0003אוסר אפילו בהנאה.\u0004","\u0003אמר רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003אבא בר נחמני אמר רב חסדא אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בלשון אחרת: \u0003אמר רב חסדא אמר זעירי: הלכה כר' שמעון. איכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת, \u0003אמר רב חסדא: אמר לי אבא בר חנן, הכי\u0004 \u0005[כך]\u0006 \u0003אמר זעירי: הלכה כר' שמעון.\u0004 ואולם בסופו של דבר מסכמת הגמרא: \u0003ואין הלכה כר' שמעון.\u0004","שנינו במשנה: \u0003נטל חבית וזרקה בחמתו לבור, זה היה מעשה והכשירו. אמר רב אשי: כל שבזב\u0004 הוא \u0003טמא\u0004 כלומר, כל אופן שמגעו של הזב מטמא, הרי פעולה כגון זו \u0003בגוי\u0004 ביין \u0003עושה יין נסך, כל שבזב טהור\u0004 — \u0003בגוי אינו עושה יין נסך.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב הונא לרב אשי\u0004 ממה ששנינו: \u0003נטל את החבית וזרקה בחמתו לבור, זה היה מעשה בבית שאן והכשירו.\u0004 ונדייק: אם זרקו \u0003בחמתו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 הכשירו, אם זרקו \u0003שלא בחמתו\u0004 — \u0003לא\u0004 היו מכשירים. ואילו בזב, אם זרק דבר מידו על דבר אחר — אינו נטמא!"],["השיב לו: \u0003התם דקאזיל מיניה ומיניה\u0004 \u0005[שם\u0006 מדובר \u0005שהולך\u0006 ומתגלגל הכלי \u0005ממנו וממנו]\u0006 כלומר, שאינו זורקו, אלא דוחקו ומגלגלו עד שמגיע לבור. ולכן כשעושה זאת שלא בחמתו אנו חוששים למגעו.","\u0003המטהר יינו של נכרי\u0004 כלומר, שהוא עושה יין מענבים של גוי, בכשרות, כדי למוכרו לישראל, ועדיין לא שילם לגוי, \u0003ונותנו ברשותו\u0004 של הגוי \u0003(ו)בבית הפתוח לרשות הרבים, בעיר שיש בה גוים וישראלים\u0004 — \u0003מותר\u0004 היין, משום שהגוי חושש שהישראלים רואים אם הוא נוגע ביין. אבל אם היה זה \u0003בעיר שכולה גוים\u0004 — \u0003אסור, עד שישב\u0004 אדם מישראל \u0003ו\u0004יהא \u0003משמר\u0004 את היין.","\u0003ואין השומר צריך להיות יושב ומשמר\u0004 בכל רגע, אלא \u0003אף על פי שהוא יוצא ונכנס\u0004 — \u0003מותר. ר' שמעון בן אלעזר אומר: רשות גוים אחת היא,\u0004 וכאשר יבוארו הדברים בגמרא.","\u0003המטהר יינו של נכרי ונותנו ברשותו\u0004 של הגוי, \u0003והלה\u0004 הגוי \u0003כותב לו: \"התקבלתי ממך מעות\"\u0004 — \u0003מותר,\u0004 משום שכיון שעכשיו היין נחשב כשל הישראל אין הגוי מעז לגעת בו. \u0003אבל אם\u0004 במקרה ש\u0003ירצה ישראל להוציא\u0004 את היין משם \u0003ואינו מניחו\u0004 הגוי להוציאו משם \u0003עד שיתן לו את מעותיו\u0004 (למרות שכתב \"התקבלתי\"), \u0003זה היה מעשה בבית שאן ואסרו,\u0004 משום שבמקרה זה הגוי סבור שהיין ממושכן לו, ואינו מתיירא לגעת בו.","על המשנה המבחינה בין עיר שיש בה ישראלים ועיר שאין בה ישראלים, שואלים: \u0003בעיר שכולה גוים נמי\u0004 \u0005[גם כן],\u0006 \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003רוכלין\u0004 ישראלים \u0003המחזירין בעיירות,\u0004 ויחשוש הגוי שמא רוכלים ישראלים אלה יראו את מעשיו ויימנע מלנגוע ביין! \u0003אמר שמואל:\u0004 מדובר \u0003בעיר שיש לה דלתים ובריח,\u0004 והוא יודע מתי נכנסים אנשים זרים לעיר.","ועל מה ששנינו שבעיר שיש בה ישראלים צריך שיהא הבית שבו היין פתוח לרשות הרבים, \u0003אמר רב יוסף: וחלון\u0004 של ישראל פתוח לאותו מקום \u0003כרשות הרבים דמי\u0004 \u0005[נחשב],\u0006 \u0003ו\u0004כן \u0003אשפה\u0004 (מקום שמשליכים בו גרוטאות וכיוצא בהן) כיון שהולכים ועומדים עליה רבים \u0003כרשות הרבים דמי\u0004 \u0005[נחשב],\u0006 \u0003ודיקלא\u0004 \u0005[ודקל]\u0006 נמצא סמוך למקום — \u0003כרשות הרבים דמי\u0004 \u0005[נחשב],\u0006 משום שהגוי חושש שאדם העולה בדקל יראנו.","אם היה \u0003פסיק רישיה\u0004 \u0005[חתוך ראשו]\u0006 של הדקל — \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אחא ורבינא, חד אסר\u0004 \u0005[אחד\u0006 מהם \u0005אוסר],\u0006 \u0003וחד שרי\u0004 \u0005[ואחד\u0006 מהם \u0005מתיר].\u0006 ומפרטים: \u0003מאן דאסר\u0004 \u0005[מי שאוסר]\u0006 סבור שבדקל שכרות ראשו, הואיל ואין פירות צומחים בו \u0003למה ליה דסליק התם\u0004 \u0005[לו שיעלה לשם],\u0006 ולכן אינו חושש שיעלו בראש הדקל ויראוהו. \u0003ומאן דשרי\u0004 \u0005[ומי שמתיר]\u0006 סבור: \u0003זימנא דאבדה ליה\u0004 \u0005[פעמים שאובדת לו]\u0006 \u0003בהמה\u0004 לאדם, \u0003וסליק לעיוני בתרה\u0004 \u0005[ועולה\u0006 על הדקל \u0005כדי לחפש אותה\u0006 מרחוק\u0005],\u0006 ולכן חושש הגוי ואינו נוגע, שמא יראו מה הוא עושה ביין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אחד הלוקח ואחד השוכר בית בחצירו של גוי ומילאהו\u0004 ישראל \u0003יין, וישראל דר באותה חצר\u0004 — \u0003מותר\u0004 יין זה, \u0003ואף על פי שאין מפתח\u0004 של הבית \u0003וחותם בידו\u0004 של ישראל."],["אם היה ישראל דר \u0003בחצר אחרת\u0004 — \u0003מותר, והוא\u0004 (דווקא בזמן) \u0003שמפתח\u0004 של אותו בית \u0003וחותם\u0004 של היין \u0003בידו\u0004 של ישראל.","\u0003המטהר יינו של גוי\u0004 והיין נמצא \u0003ברשותו\u0004 של הגוי, \u0003וישראל דר באותה חצר\u0004 — \u0003מותר, והוא שמפתח וחותם בידו\u0004 של הישראל. ומעירים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לתנא\u0004 (שונה המשניות), \u0003תני\u0004 \u0005[שנה\u0006 כך\u0005]:\u0006 \u0003אף על פי שאין מפתח וחותם בידו\u0004 — \u0003מותר.\u0004","וממשיכה הברייתא: אם היה הישראל דר \u0003בחצר אחרת\u0004 — \u0003אסור, אף על פי שמפתח וחותם בידו,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אוסרין,\u0004 \u0003עד שיהא שומר יושב ומשמר, או עד שיבא ממונה הבא לקיצין\u0004 בזמנים קבועים.","ושואלים: \u0003חכמים אהייא\u0004 \u0005[על איזה\u0006 מקרה בברייתא מתייחסים דבריהם\u0005]?\u0006 \u0003אילימא אסיפא\u0004 \u0005[אם תאמר על הסוף]\u0006 — \u0003תנא קמא נמי מיסר קא אסר\u0004 \u0005[התנא הראשון,\u0006 ר' מאיר, \u0005גם כן אוסר]!\u0006 \u0003ואלא\u0004 תאמר כי הכוונה היא \u0003ארישא דסיפא\u0004 \u0005[על ראשה של\u0006 הפיסקה \u0005האחרונה],\u0006 במטהר יינו של הגוי והישראל דר באותה חצר — \u0003והא קאמר ליה\u0004 \u0005[והרי אמר לו]\u0006 \u0003ר' יוחנן לתנא,\u0004 \u0003תני\u0004 \u0005[שנה]\u0006 בהלכה זו: \u0003אף על פי שאין מפתח וחותם בידו\u0004 — מותר, ובוודאי אין ר' יוחנן חולק על דעת חכמים! \u0003ואלא\u0004 יש לומר שחכמים מתייחסים \u0003אסיפא דרישא\u0004 \u0005[לסופה\u0006 של הפיסקה \u0005הראשונה],\u0006 ביינו של ישראל המונח בבית בחצירו של גוי, \u0003דקאמר תנא קמא\u0004 \u0005[שאומר התנא הראשון]:\u0006 אם ישראל \u0003בחצר אחרת\u0004 — \u0003מותר, והוא שמפתח וחותם בידו. וחכמים אומרים: לעולם אסור, עד שיהא שומר יושב ומשמר, או עד שיבא ממונה הבא לקיצין.\u0004","","ולגופם של דברי חכמים תוהים: וכי \u0003ממונה בא לקיצין\u0004 בזמנים קבועים \u0003גריעותא\u0004 \u0005[גריעות]\u0006 \u0003הוא,\u0004 שהרי יודע הגוי מתי בא השומר, ובין הזמנים הללו יכול לעשות מה שירצה! \u0003אלא\u0004 יש לתקן: \u0003עד שיבא ממונה שאינו בא לקיצין,\u0004 אלא בכל עת שעולה בדעתו. על מה ששנינו במשנה כי המטהר יינו של גוי ונתנו ברשותו של הגוי — היין אסור עד שיהא שם שומר, \u0003ר' שמעון בן אלעזר אומר: רשות גוים אחת היא. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003ר' שמעון בן אלעזר להקל\u0004 בא \u0003או להחמיר\u0004 בא? \u0003רב יהודה אמר\u0004 בשם \u0003זעירי: להקל\u0004 בא, \u0003רב נחמן אמר\u0004 בשם \u0003זעירי: להחמיר.\u0004","ומסבירים את השיטות: \u0003רב יהודה אמר זעירי להקל, והכי קאמר תנא קמא\u0004 \u0005[וכך אמר התנא הראשון]:\u0006 \u0003כשם שברשותו\u0004 של הגוי בעל היין \u0003אסור, כך\u0004 אם היה היין \u0003ברשות גוי אחר נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור,\u0004 שמא נתן לבעל היין לגעת בו, \u0003ו\u0004טעם הדבר כי \u0003חיישינן לגומלין\u0004 \u0005[חוששים אנו\u0006 שהם \u0005גומלים\u0006 זה לזה\u0005],\u0006 שיגמול לו בעל היין בפעם אחרת כעין זה, ולכן אין ההוא מספר על כך. ואילו \u0003ר' שמעון בן אלעזר אומר: במה דברים אמורים\u0004 שאסור — כשהיה היין \u0003ברשותו\u0004 של הגוי בעל היין, \u0003אבל ברשות גוי אחר\u0004 — \u0003מותר,\u0004 שחושש הוא לגשת ליין ברשותו של אחר, שמא ייוודע הדבר, \u0003ולא חיישינן\u0004 \u0005[ואין אנו חוששים]\u0006 \u0003לגומלין.\u0004 ואילו \u0003רב נחמן אמר\u0004 בשם \u0003זעירי\u0004 שכוונתו \u0003להחמיר, והכי קאמר תנא קמא\u0004 \u0005[וכך אמר התנא הראשון]:\u0006 \u0003במה דברים אמורים\u0004 שאסור? כשהיה היין \u0003ברשותו\u0004 של הגוי בעל היין, \u0003אבל ברשות גוי אחר\u0004 — \u0003מותר, ולא חיישינן\u0004 \u0005[ואין אנו חוששים]\u0006 \u0003לגומלין.\u0004 ואילו \u0003ר' שמעון בן אלעזר אומר: כל רשות גוים אחת היא,\u0004 שאנו חוששים שהם גומלים זה לזה, ואינם מספרים.","","","","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב נחמן אמר\u0004 בשם \u0003זעירי\u0004 שר' שמעון בן אלעזר בא \u0003להחמיר,\u0004 ששנינו ש\u0003אמר ר' שמעון בן אלעזר: כל רשות גוים אחת היא מפני הרמאין,\u0004 ומשמע שהוא המחמיר בזה.","מסופר, \u0003דבי פרזק רופילא\u0004 \u0005[\u0006אנשי \u0005בית פרזק השר]\u0006 \u0003אותיבו חמרא גבי אריסייהו\u0004 \u0005[הניחו יין\u0006 שטיהרו ישראל \u0005אצל אריסיהם\u0006 הגוים\u0005],\u0006 \u0003סבור רבנן קמיה דרבא למימר\u0004 \u0005[סברו חכמים\u0006 שהיו \u0005לפני רבא לומר]:\u0006 \u0003כי חיישינן\u0004 \u0005[כאשר חוששים אנו]\u0006 \u0003לגומלין\u0004 — \u0003הני מילי היכא דקא מותיב האי גבי האי\u0004 \u0005[דברים אלה\u0006 אמורים \u0005כאשר זה מניח אצל זה],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003כיון דאריסיה לאו דרכיה לאותוביה בי פרזק רופילא\u0004 \u0005[שהאריס אין דרכו להניח\u0006 דברים \u0005בבית פרזק השר],\u0006 \u0003לגומלין לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא: אדרבה, אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003לא חיישינן\u0004 \u0005[\u0006ש\u0005אין אנו חוששים]\u0006 \u0003לגומלין, הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003היכא דלא מירתת מיניה\u0004 \u0005[במקום שאינו מפחד ממנו\u0006 הגוי האחר\u0005],\u0006 \u0003אבל הכא\u0004 \u0005[כאן],\u0006 באריסים אלה של פרזק, \u0003כיון דמירתת מיניה\u0004 \u0005[ש\u0006הוא \u0005מפחד ממנו]\u0006 — \u0003מחפי עליה זכותא\u0004 \u0005[\u0006הרי הוא \u0005מחפה עליו לזכות]\u0006 ובוודאי לא יספר מעשיו.","מסופר, \u0003ההוא כרכא דהוה יתיב ביה חמרא\u0004 \u0005[כרך אחד שהיה מונח בו יין]\u0006 של \u0003ישראל, אשתכח\u0004 \u0005[נמצא]\u0006 \u0003גוי דהוה קאי ביני דני\u0004 \u0005[שהיה עומד בין החביות\u0006 של היין\u0005],\u0006 \u0003אמר רבא: אם\u0004 כשיגלו אותו נוגע ביין הריהו \u0003נתפס עליו כגנב\u0004 — \u0003חמרא שרי\u0004 \u0005[היין מותר],\u0006 שמפני שהוא מפחד שיתפסוהו אינו מתפנה לנסך, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — היין \u0003אסור\u0004",""]]};
